// Üretilen dosya: tool/ozgun/uret.py. Kimya · Tepkime hızı, denge ve enerji (orta).
const ozChemistry13Orta = <(String, String, List<String>, String)>[
  ('Sabit hacimli kapalı bir kapta sabit sıcaklıkta 2N₂O₅(g) → 4NO₂(g) + O₂(g) tepkimesi yürürken tepkimenin ilerleyişi kaptaki toplam basınç ölçülerek izlenebilir. Bunun nedeni nedir?', 'Gaz mol sayısı 2\'den 5\'e çıktığı için toplam basınç artar', ['Gaz tanecikleri arasındaki çekim azaldığı için toplam basınç artar', 'Sıcaklık yükseldiği için toplam basınç artar', 'Tepkime ısı verdiği için basınç doğrusal azalır'], 'Sabit T ve V\'de basınç gaz mol sayısı ile orantılıdır. Girenlerde 2 mol, ürünlerde 5 mol gaz olduğundan basınç zamanla artar.'),
  ('Etil asetatın NaOH ile sabunlaşması (CH₃COOC₂H₅ + OH⁻ → CH₃COO⁻ + C₂H₅OH) sırasında çözeltinin elektrik iletkenliği zamanla azalır. Bu azalma neden olur?', 'Hareketli OH⁻ yerine daha az hareketli CH₃COO⁻ geçer', ['Çözeltideki toplam iyon sayısının yaklaşık iki katına çıkması', 'Etil asetatın iyonlaşarak iletkenliği artırması', 'Oluşan etanolün çözeltiye elektron vermesi'], 'OH⁻ iyonu çözeltide çok yüksek iyonik hareketliliğe sahiptir; yerine geçen asetat iyonu daha yavaştır. Bu nedenle iletkenlik hız ölçümünde kullanılır.'),
  ('A → B tepkimesinde A\'nın derişimi t = 0\'da 0,80 M, 30. saniyede 0,50 M, 60. saniyede 0,30 M ölçülüyor. 30–60 saniye aralığındaki ortalama hız kaç M/s\'dir?', '0,0067', ['0,01000', '0,0050', '0,0200'], 'Ortalama hız = |Δ[A]|/Δt = (0,50 − 0,30)/30 = 0,0067 M/s. İlk 30 saniyede hız 0,010 M/s olduğundan hız zamanla azalmıştır.'),
  ('Kinetik deneylerde mertebe tayininde genellikle tepkimenin yalnız ilk anlarındaki hız (başlangıç hızı) kullanılır. Bu tercihin başlıca nedeni hangisidir?', 'Girenlerin tükenmesi ve geri tepkime etkisi henüz ihmal edilebilir', ['Başlangıçta aktifleşme enerjisi sıfır olduğundan hız ölçümü kolaylaşır', 'Başlangıçta katalizör henüz etkisini göstermediği için hız saf biçimde ölçülür', 'Başlangıç hızı her zaman en küçük hızdır'], 'İlk anlarda giren derişimleri bilinen değerlerine çok yakındır ve ürün birikimi azdır. Bu nedenle hız–derişim ilişkisi temiz biçimde yorumlanır.'),
  ('2A + B → 3C tepkimesinde C\'nin oluşum hızı 0,30 M/s ise tepkimenin genel hızı (r), yani katsayılara bölünmüş hız kaç M/s\'dir?', '0,10', ['0,15', '0,30', '0,600'], 'Tepkime hızı r = (1/3)·Δ[C]/Δt = 0,30/3 = 0,10 M/s olur. Bu durumda A\'nın harcanma hızı 0,20, B\'ninki 0,10 M/s\'dir.'),
  ('A + B → ürün tepkimesinde B, A\'nın yaklaşık 100 katı fazla alınarak deney yapılıyor. Deney sırasında B\'nin derişimi pratik olarak değişmediğinden hız, yalnızca [A]\'ya bağlıymış gibi davranıyor. Bu duruma ne denir?', 'Yalancı (görünür) birinci mertebe', ['Sıfırıncı mertebe tepkime', 'Zincir tepkimesi', 'Otokataliz'], 'Büyük fazlalıktaki B\'nin derişimi sabit kabul edilip k\'ye katılır; tepkime A\'ya göre birinci mertebeymiş gibi izlenir.'),
  ('Bir tepkimede A\'nın derişimi 0, 10 ve 20. dakikalarda sırasıyla 1,00 M, 0,50 M ve 0,25 M ölçülüyor. Bu veriler tepkimenin mertebesi hakkında ne gösterir?', 'Yarı ömür sabit olduğundan birinci mertebedir', ['Derişim doğrusal azaldığından sıfırıncı mertebedir', 'Yarı ömür giderek uzadığından ikinci mertebedir', 'Yarı ömür giderek kısaldığından yarı mertebedir'], 'Derişim her 10 dakikada yarıya iniyor; yarı ömrün başlangıç derişiminden bağımsız ve sabit olması birinci mertebe kinetiğinin özelliğidir.'),
  ('Bir tepkimede A\'nın derişimi 0, 10, 20 ve 30. saniyelerde sırasıyla 1,00; 0,80; 0,60 ve 0,40 M bulunuyor. Aşağıdakilerden hangisi doğrudur?', 'Hız sabit (0,02 M/s), tepkime sıfırıncı mertebedir', ['Hız artmaktadır, tepkime birinci mertebedir', 'Hız yarıya düşmektedir, tepkime ikinci mertebedir', 'Hız zamanla azalmaktadır, tepkime birinci mertebedir'], 'Her 10 saniyede derişim sabit 0,20 M azalıyor; hız derişimden bağımsızdır ve 0,02 M/s\'dir. Bu sıfırıncı mertebe davranışıdır.'),
  ('Sıfırıncı mertebeden bir tepkimede k = 0,020 M/s ve [A]₀ = 0,50 M ise A\'nın tamamen tükenmesi kaç saniye sürer?', '25', ['10', '50', '0,04'], 'Sıfırıncı mertebede [A] = [A]₀ − kt olduğundan t = 0,50/0,020 = 25 s.'),
  ('Birinci mertebeden bir tepkime için ln[A]\'nın zamana karşı grafiği çizilirse ne elde edilir?', 'Doğru çıkar ve eğimi −k\'dir', ['Doğru çıkar ve eğimi +1/k\'dir', 'Parabol çıkar', 'Yatay doğru çıkar'], 'ln[A] = ln[A]₀ − kt olduğundan doğrusaldır ve eğimi −k\'dir; kesişim noktası ln[A]₀ değerini verir.'),
  ('İkinci mertebeden (r = k[A]²) bir tepkimede hangi grafik doğrusal olur ve eğimi neye eşittir?', '1/[A] – zaman; eğim +k', ['ln[A] – zaman grafiği; eğim −k', '[A] – zaman grafiği; eğim −k', '[A]² – zaman grafiği; eğim +k'], 'İntegre edilmiş hız yasası 1/[A] = 1/[A]₀ + kt biçimindedir; 1/[A] zamana karşı doğrusaldır ve eğimi k\'dir.'),
  ('Sıfırıncı mertebeden bir tepkimede başlangıç derişimi iki katına çıkarılırsa yarı ömür (t½ = [A]₀/2k) nasıl değişir?', 'İki katına çıkar', ['Değişmez', 'Yarıya iner', 'Dört katına çıkar'], 'Sıfırıncı mertebede t½ = [A]₀/(2k) olduğundan [A]₀ ile doğru orantılıdır; derişim iki katına çıkınca yarı ömür de iki katına çıkar.'),
  ('Arrhenius denklemi k = A·e^(−Ea/RT) bağıntısındaki A çarpanı (frekans çarpanı) neyi yansıtır?', 'Çarpışma sıklığını ve yönelim olasılığını', ['Katalizörün tepkimeye giren maddelerle birleşme hızını', 'Tepkimenin entalpi değişimini', 'Ürünlerin kararlılığını'], 'A çarpanı birim zamandaki çarpışma sayısı ile bu çarpışmaların uygun yönelimde olma oranını içerir; e^(−Ea/RT) terimi ise yeterli enerjiye sahip taneciklerin oranını verir.'),
  ('Bir tepkime için ln k değerleri 1/T\'ye karşı çizildiğinde eğimi −6000 K olan bir doğru elde ediliyor. Tepkimenin aktifleşme enerjisi yaklaşık kaç kJ/mol\'dür? (R = 8,314 J/(mol·K))', '50', ['6', '720', '0,72'], 'Eğim = −Ea/R olduğundan Ea = 6000 K × 8,314 J/(mol·K) ≈ 49 900 J/mol ≈ 50 kJ/mol.'),
  ('Aynı sıcaklık artışı uygulandığında aktifleşme enerjisi büyük olan tepkimenin hız sabitindeki göreli artış, küçük olana göre nasıl olur?', 'Daha büyük olur', ['Daha küçük olur', 'Aynı olur', 'Önce artar sonra azalır'], 'ln k\'nın 1/T\'ye göre eğimi −Ea/R olduğundan Ea büyüdükçe k sıcaklığa daha duyarlıdır; aynı ısıtmada göreli artış daha fazladır.'),
  ('Aktifleşme enerjisi sıfıra çok yakın olan bir tepkimenin hız sabiti için hangisi söylenebilir?', 'Sıcaklıkla çok az değişir', ['Sıcaklık arttıkça çok hızlı artar', 'Sıcaklık arttıkça azalır', 'Katalizör yokluğunda sıfırdır'], 'Ea ≈ 0 ise e^(−Ea/RT) ≈ 1 olur ve k ≈ A kalır; sıcaklık değişimi hız sabitini belirgin biçimde etkilemez.'),
  ('Bir katalizör eklendiğinde taneciklerin enerji dağılımı eğrisi ve eşik (aktifleşme) enerjisi için ne söylenebilir?', 'Eğri değişmez, eşik enerjisi düşer', ['Eğri sağa kayar, eşik enerjisi değişmez', 'Eğri yassılaşır, eşik enerjisi artar', 'Eğri sola kayar, eşik enerjisi yükselir'], 'Katalizör taneciklerin enerji dağılımını değiştirmez; eşik enerjisini düşürerek bu eşiği aşan tanecik oranını artırır.'),
  ('İki basamaklı bir tepkimenin enerji profilinde birinci tepe ikinci tepeden daha yüksektir. Bu durumda hız belirleyen basamak hangisidir?', 'Birinci basamak', ['İkinci basamak', 'Her iki basamak eşit etkilidir', 'Ara ürünün oluştuğu çukur'], 'En yüksek enerji bariyerine sahip basamak en yavaş basamaktır ve toplam hızı belirler. Burada bu birinci basamaktır.'),
  ('Bir tepkime mekanizmasının kabul edilebilir olması için hangi iki koşulu birlikte sağlaması gerekir?', 'Basamaklar toplamı genel denklemi vermeli, hız ifadesi deneyle uyuşmalı', ['Her basamak aynı hızda olmalı, ara ürün sayısı en az üç olmalı', 'Katalizör içermeli, tüm basamaklar ekzotermik olmalı', 'Tüm basamaklar tek moleküllü olmalı, hız ifadesi derişimlerden bağımsız olmalı'], 'Mekanizma, ara ürünler elendiğinde toplam denklemi vermeli ve deneysel hız yasasını açıklamalıdır. Bunlar sağlanınca mekanizma kabul edilebilir (kanıtlanmış olmaz).'),
  ('Mertebe ve moleküleriyet kavramları karşılaştırıldığında hangisi doğrudur?', 'Mertebe kesirli olabilir, moleküleriyet tam sayıdır', ['Moleküleriyet kesirli olabilir, mertebe her zaman tam sayıdır', 'İkisi de deneyle belirlenir', 'Her tepkimede ikisi birbirine eşittir'], 'Moleküleriyet temel bir basamakta çarpışan tanecik sayısıdır, bu yüzden pozitif tam sayıdır. Mertebe deneysel verilerden bulunur ve 1/2, 3/2 gibi kesirli değerler alabilir.'),
  ('Üç tanecikli (termoleküler) temel basamakların oldukça seyrek görülmesinin nedeni nedir?', 'Üç taneciğin aynı anda uygun çarpışma olasılığı çok düşüktür', ['Üç taneciğin toplam kütlesi çarpışmanın gerçekleşmesini engeller', 'Üç tanecik arasındaki itme kuvvetleri çarpışmayı imkânsız kılar', 'Üçlü çarpışmalarda aktifleşme enerjisi her zaman negatif olur'], 'Aynı anda üç taneciğin uygun biçimde bir araya gelmesi iki taneciğin çarpışmasından çok daha az olasıdır; çoğu mekanizma bu yüzden bi- ya da unimoleküler basamaklardan kurulur.'),
  ('Zincir tepkimeleri başlama, ilerleme ve sonlanma basamaklarıyla yürür. Aşağıdakilerden hangisi \'ilerleme\' basamağını tanımlar?', 'Bir radikalin tüketilip yenisinin oluştuğu basamak', ['İki radikalin birleşip kararlı molekül verdiği basamak', 'Kararlı bir molekülden ilk radikallerin oluştuğu basamak', 'Katalizörün ortamdan uzaklaştığı basamak'], 'İlerleme basamağında bir radikal bir molekülle tepkimeye girer ve yeni bir radikal doğurur; böylece zincir sürer. Başlama radikal üretir, sonlanma radikalleri tüketir.'),
  ('Farklı iki tepkimeden birinin aktifleşme enerjisi 40 kJ/mol, diğerinin 80 kJ/mol\'dür. A çarpanları aynı kabul edilirse oda sıcaklığında hız sabitleri için hangisi doğrudur?', 'Ea\'sı 40 olanın hız sabiti çok daha büyüktür', ['İkisinin hız sabiti eşittir', 'Ea\'sı 80 kJ/mol olanın hız sabiti daha büyüktür', 'Ea\'sı 40 kJ/mol olanın hız sabiti sıfırdır'], 'k = A·e^(−Ea/RT) olduğundan A eşitse düşük Ea daha büyük k verir. 40 kJ/mol fark oda sıcaklığında yaklaşık 10⁷ kat fark oluşturur.'),
  ('Kinetik teoriye göre gaz karışımında saniyede milyarlarca çarpışma olmasına karşın birçok gaz tepkimesi yavaştır. Hız sabitini belirleyen aşağıdakilerden hangisi bu durumu en iyi açıklar?', 'Çarpışmaların çok azının gerekli enerji ve yönelimi sağlaması', ['Gaz taneciklerinin birbirine yaklaşmadan, temas etmeden hareket etmesi', 'Çarpışmaların kimyasal bağları hiçbir koşulda etkilememesi', 'Tüm çarpışmaların ürüne dönüşüp tepkimeyi hemen bitirmesi'], 'Etkin çarpışma için hem Ea\'yı aşan enerji hem uygun yönelim gerekir. Çarpışmaların küçük bir kısmı bu iki koşulu birlikte sağlar.'),
  ('Aşağıdaki katalitik olaylardan hangisi homojen katalize örnektir?', 'Sulu H₂O₂ çözeltisinin ayrışmasının I⁻ iyonlarıyla hızlanması', ['Haber–Bosch yönteminde N₂ ile H₂\'nin katı demir yüzeyinde birleşmesi', 'Egzoz gazlarındaki CO\'nun katı platin yüzeyinde CO₂\'ye yükseltgenmesi', 'Sulu H₂O₂ çözeltisine katı MnO₂ tozu atılınca O₂ çıkışının hızlanması'], 'Homojen katalizde katalizör girenlerle aynı fazdadır. Sulu çözeltideki I⁻ ile H₂O₂ aynı fazdadır; diğer seçeneklerde katalizör katı, giren gaz ya da sıvıdır.'),
  ('Katı yüzeyli heterojen katalizde tepkime basamaklarının ilki genellikle hangisidir?', 'Girenlerin katalizör yüzeyine tutunması', ['Ürünlerin yüzeyden tamamen ayrılıp uzaklaşması', 'Katalizör atomlarının çözeltiye geçip girenlerle birleşmesi', 'Katalizörün erime noktasına kadar ısıtılması sonucu sıvılaşması'], 'Heterojen katalizde giren molekül önce yüzeydeki aktif bölgelere tutunur, bağları zayıflar, tepkime olur ve ürün yüzeyden ayrılır (desorpsiyon).'),
  ('Katalitik konvertörlü araçlarda kurşunlu benzin kullanılmasının yasaklanmasının önemli bir nedeni nedir?', 'Kurşun katalizör yüzeyini kaplayıp etkinliğini yok eder', ['Kurşun, konvertördeki tepkimelerin ΔH değerini artırır', 'Kurşun platinin erime noktasını belirgin biçimde düşürür', 'Kurşun, motorun silindir hacmini küçülterek verimi azaltır'], 'Kurşun gibi maddeler katalizörün aktif yüzeyine kalıcı biçimde tutunup onu işlevsiz bırakır; bu olaya katalizör zehirlenmesi denir.'),
  ('Bir katalizör, ΔG değeri pozitif olan bir tepkimeyi aşağıdakilerden hangisi şeklinde etkiler?', 'Kendiliğinden yürüyen hâle getiremez', ['Tepkimeyi kendiliğinden yürüyen hâle getirir', 'ΔG değerini negatife çevirir', 'Tepkimeye enerji sağlayıp ΔH\'yi düşürür'], 'Katalizör yalnız hız ve yolu etkiler; girenlerle ürünlerin serbest enerjisini değiştirmez. Termodinamik olarak istemsiz bir tepkimeyi istemli yapamaz.'),
  ('Bir enzimin etki ettiği madde (substrat) derişimi sabit enzim miktarında giderek artırılırsa tepkime hızı en sonunda neden bir üst değerde sabitlenir?', 'Tüm aktif merkezler substratla doyar', ['Enzim substratı tamamen tüketir', 'Substrat enzimi çözer', 'Aktifleşme enerjisi sonsuza çıkar'], 'Yüksek substrat derişiminde tüm enzim molekülleri aktif merkezlerinde substrat taşır; hız maksimum değere (Vmax) ulaşır ve daha fazla substrat hızı artırmaz.'),
  ('Michaelis–Menten kinetiğinde Michaelis sabiti (Km) neyi ifade eder?', 'Hızın Vmax/2 olduğu substrat derişimini', ['Enzimin en yüksek sıcaklıktaki hızını', 'Enzimin kütlesini', 'Ürün derişiminin yarıya indiği süreyi'], 'Km, tepkime hızının Vmax/2 olduğu substrat derişimidir. Küçük Km, enzimin substrata ilgisinin yüksek olduğunu gösterir.'),
  ('Un, kömür ya da şeker tozu depolayan tesislerde havada asılı kalan toz patlamalarının yaşanması hangi etkenle açıklanır?', 'Çok ince tozun yüzey alanının ve oksijenle temasının büyük olması', ['Tozların oda sıcaklığında aktifleşme enerjisinin sıfır olması', 'Toz taneciklerinin kendilerinin güçlü bir katalizör olması', 'Havadaki azot gazının tozları önceden ısıtması'], 'Katı madde ince toz hâline gelince temas yüzeyi çok büyür; kıvılcımla hava ile karışmış toz çok hızlı yanar ve patlama olabilir. Aynı madde yığın hâlinde yavaş yanar.'),
  ('Etanol buharı yaklaşık 300 °C\'de bakır katalizör üzerinden geçirilirse asetaldehit, alüminyum oksit üzerinden geçirilirse eten oluşur. Bu örnek katalizörlerin hangi özelliğini gösterir?', 'Seçici olmaları', ['Hep aynı ürünü vermeleri', 'Tepkimede harcanmaları', 'Dengeyi tamamen ürünlere kaydırmaları'], 'Aynı giren, farklı katalizörlerle farklı yollardan farklı ürünlere yönlendirilebilir. Katalizörün bu özelliğine seçicilik denir.'),
  ('Bir katalizörün tepkimede kullanılmasına ilişkin hangisi doğrudur?', 'Kimyasal olarak değişmeden geri kazanılır, fiziksel hâli değişebilir', ['Tepkime sonunda mutlaka tamamen tükenmiş olarak sıfır gram kalır', 'Girenlerle stokiyometrik oranda tepkimeye girip tüketilir', 'Tepkimeye katılması için her zaman gaz hâlinde bulunmalıdır'], 'Katalizör mekanizmada harcanıp yeniden oluşur; kimyasal bileşimi değişmez. Yüzeyi pürüzlenme gibi fiziksel değişiklikler gösterebilir.'),
  ('Bir enzimli tepkime sıcaklığa karşı incelenirken hız önce artıyor, belirli bir sıcaklıktan sonra hızla düşüyor. Bu eğriyi yorumlayan öğrenci hangi sonuca varmalıdır?', 'Artış etkin çarpışma, düşüş enzim yapısının bozulmasıyla ilgilidir', ['Hem artış hem düşüş yalnızca aktifleşme enerjisindeki değişimdendir', 'Düşüş yalnızca substratın hızla tükenmesinden kaynaklanır', 'Düşüş katalizör kütlesinin sıcaklıkla artmasından kaynaklanır'], 'İlk bölgede sıcaklık arttıkça etkin çarpışma çoğalır; optimumun ötesinde protein yapısı bozulduğundan hız düşer.'),
  ('Tepkime hızını artırmak için katalizör eklemek yerine sıcaklığı yükseltmenin bir sakıncası, ürünlerin kararlılığı açısından hangisidir?', 'Isıya duyarlı maddeler bozunabilir, yan tepkimeler hızlanabilir', ['Sıcaklık yükselince tepkime hızı kural olarak sürekli düşer', 'Sıcaklık artışı tepkimenin ΔH değerini sıfıra eşitler', 'Isı yalnızca katalizör moleküllerini etkiler, girenleri etkilemez'], 'Yüksek sıcaklık yan tepkimeleri ve bozunmayı da hızlandırabilir. Katalizör ise çoğu zaman belirli tepkimeyi seçici biçimde hızlandırır.'),
  ('1 L\'lik kapta 1 mol CO ile 1 mol H₂O(g) bulunuyor. CO + H₂O ⇌ CO₂ + H₂ dengesinin Kc değeri aynı sıcaklıkta 4 ise dengede kaç mol CO₂ oluşmuştur?', '0,67', ['0,500', '0,80', '0,33'], 'x mol CO₂ oluşursa x²/(1−x)² = 4 olur; x/(1−x) = 2 ve x = 2/3 ≈ 0,67 mol bulunur.'),
  ('1 L\'lik kaba 0,10 mol N₂O₄ konup N₂O₄(g) ⇌ 2NO₂(g) dengesi kuruluyor. Dengede [NO₂] = 0,040 M ölçüldüğüne göre Kc kaçtır?', '0,02', ['0,50', '0,0016', '0,04'], 'NO₂ 0,040 M ise N₂O₄ 0,020 M harcanmıştır; [N₂O₄] = 0,080 M. Kc = (0,040)²/0,080 = 0,02.'),
  ('2NO(g) + O₂(g) ⇌ 2NO₂(g) dengesinde [NO] = 0,10 M, [O₂] = 0,20 M ve [NO₂] = 0,40 M\'dir. Kc kaçtır?', '80', ['8', '40', '160'], 'Kc = [NO₂]²/([NO]²[O₂]) = 0,16/(0,01·0,20) = 80.'),
  ('Kc = 9 olan A + B ⇌ C + D dengesi için 1 L\'lik bir kaba A ve B\'den birer mol konuyor. Denge kurulduğunda A kaç M kalır?', '0,25', ['0,75', '0,500', '0,10'], 'C ve D için x alınırsa x²/(1−x)² = 9 ve x = 0,75 bulunur; kalan A = 1 − 0,75 = 0,25 M.'),
  ('Bir kapta H₂ + I₂ ⇌ 2HI dengesi kurulmuş ve dengede 2 mol H₂, 2 mol I₂, 6 mol HI bulunmaktadır. Kap hacmi bilinmediği hâlde Kc hesaplanabilir. Kc kaçtır?', '9', ['3', '18', '36'], 'Gaz mol sayısı değişmediğinden (Δn = 0) hacim sadeleşir. Kc = 6²/(2·2) = 9.'),
  ('N₂(g) + 3H₂(g) ⇌ 2NH₃(g) dengesinin Kc değeri K ise 4NH₃ ⇌ 2N₂ + 6H₂ dengesinin Kc değeri nedir?', '1/K²', ['1/K', 'K²', '2,0/K'], 'Denklem tersine çevrilince K, 1/K olur; katsayılar iki katına çıkınca denge sabiti kuvvet alır: (1/K)² = 1/K².'),
  ('Sabit sıcaklıkta H₂ + I₂ ⇌ 2HI dengesine 1 mol H₂ ve 1 mol I₂ ile başlanıyor. Başka bir deneyde aynı kapta yalnız 2 mol HI ile başlanıyor. Dengeler için hangisi doğrudur?', 'İki durumda da aynı denge bileşimine ulaşılır', ['Yalnız H₂ ve I₂ ile başlanan deneyde denge kurulur', 'HI ile başlanan deneyde denge sabiti daha büyük çıkar', 'Dengeye ulaşma yönü Kc değerini değiştirir'], '2 mol HI, 1 mol H₂ + 1 mol I₂ ile aynı atom miktarını içerir. Denge sabiti yalnız sıcaklığa bağlıdır; denge hangi yönden yaklaşılırsa yaklaşılsın aynı bileşim oluşur.'),
  ('1 L\'lik kapta 1 mol N₂O₄ konuluyor ve N₂O₄ ⇌ 2NO₂ dengesinde N₂O₄\'ün %20\'si ayrışıyor. Kc kaçtır?', '0,2', ['0,05', '0,8', '1,6'], 'Dengede N₂O₄ = 0,8 M, NO₂ = 0,4 M. Kc = 0,4²/0,8 = 0,2.'),
  ('Bir tepkimenin Kc değeri çok büyük (10²⁰) olduğu hâlde karışım günlerce tepkime vermeden duruyor. Bu durum aşağıdakilerden hangisiyle açıklanır?', 'Denge sabiti termodinamiktir, hız ise Ea\'ya bağlıdır', ['Denge sabiti büyükse tepkime mutlaka anında tamamlanır', 'Katalizör bu durumda denge sabitini sıfıra indirir', 'Kc büyükse aktifleşme enerjisi mutlaka negatiftir'], 'K, dengedeki bileşimi anlatır; tepkimenin ne kadar hızlı yürüyeceğini göstermez. Yüksek Ea, termodinamik olarak elverişli tepkimeyi çok yavaş kılabilir.'),
  ('Dengede [A] = 0,50 M, [B] = 0,50 M ve [C] = 0,25 M olan 2A + B ⇌ C tepkimesi için Kc kaçtır?', '2', ['0,5', '1', '4'], 'Kc = [C]/([A]²[B]) = 0,25/(0,25·0,50) = 2 M⁻².'),
  ('Toplam basıncın 3 atm olduğu bir dengede N₂O₄(g) ⇌ 2NO₂(g) karışımında 1 mol N₂O₄ ve 2 mol NO₂ bulunuyor. Kısmi basınçları mol kesirlerinden bularak Kp\'yi hesaplayınız.', '4 atm', ['2 atm', '1,33 atm', '0,25 atm'], 'Toplam 3 mol olduğundan P(N₂O₄) = 1 atm, P(NO₂) = 2 atm\'dir. Kp = 2²/1 = 4 atm.'),
  ('Boş bir kaba katı NH₄HS konup NH₄HS(k) ⇌ NH₃(g) + H₂S(g) dengesi kuruluyor. Denge anında toplam gaz basıncı 0,60 atm ise Kp kaçtır?', '0,09', ['0,30', '0,360', '0,60'], 'NH₃ ve H₂S eşit mol oluştuğundan her birinin kısmi basıncı 0,30 atm\'dir. Kp = 0,30 × 0,30 = 0,09 atm².'),
  ('C(k) + CO₂(g) ⇌ 2CO(g) dengesinde toplam basınç 1,0 atm olup gaz karışımında P(CO) = 0,6 atm ve P(CO₂) = 0,4 atm\'dir. Kp kaçtır?', '0,9', ['0,6', '1,5', '0,36'], 'Katı karbon ifadeye girmez. Kp = P(CO)²/P(CO₂) = 0,36/0,40 = 0,9 atm.'),
  ('N₂O₄ ⇌ 2NO₂ dengesinde Kc = 0,20 M\'dir. Bir anda [N₂O₄] = 0,50 M ve [NO₂] = 0,50 M ölçülürse sistemle ilgili hangisi doğrudur?', 'Q > K; sistem geriye (girenler yönüne) ilerler', ['Q < K; sistem ürünler yönüne ilerler', 'Q = K; sistem tam olarak dengededir', 'Q hesaplanamaz, çünkü Kp bilinmemektedir'], 'Q = 0,50²/0,50 = 0,50 > 0,20 olduğundan ürün fazladır; denge kurulana kadar NO₂ azalıp N₂O₄ artar.'),
  ('N₂O₄(g) ⇌ 2NO₂(g) tepkimesinde Kp = 2 atm\'dir. Kısmi basınçlar P(N₂O₄) = 0,5 atm ve P(NO₂) = 2 atm iken sistem hangi yönde ilerler?', 'Girenler yönünde, çünkü Q = 8 > Kp', ['Ürünler yönünde, çünkü Q = 8 > Kp', 'Ürünler yönünde, çünkü Q = 0,125 < Kp', 'Her iki yönde de ilerlemez, çünkü Q = Kp'], 'Q = 2²/0,5 = 8 olup Kp = 2\'den büyüktür; ürün fazlalığı vardır, sistem NO₂\'yi tüketerek geriye ilerler.'),
  ('Δn < 0 olan bir gaz dengesinde (örneğin CO + 2H₂ ⇌ CH₃OH) sıcaklık yeterince yüksek olduğunda, atm ve mol/L birimleriyle Kp ile Kc arasında nasıl bir ilişki bulunur?', 'Kp, Kc\'den küçüktür', ['Kp, Kc\'ye eşittir', 'Kp, Kc\'den büyüktür', 'İkisi arasında bağıntı yoktur'], 'Kp = Kc(RT)^Δn ve Δn = −2\'dir. RT 1\'den büyük olduğundan (RT)⁻² < 1 olur ve Kp < Kc çıkar.'),
  ('Boş bir kaba katı NH₄Cl konup ısıtılıyor ve NH₄Cl(k) ⇌ NH₃(g) + HCl(g) dengesi kuruluyor. Denge basıncı toplam 2 atm ise Kp kaçtır?', '1', ['2', '4', '0,5'], 'NH₃ ve HCl\'nin kısmi basınçları eşit olup her biri 1 atm\'dir. Kp = 1 × 1 = 1 atm².'),
  ('Haber–Bosch reaktöründen çıkan gaz karışımı soğutularak NH₃ sıvılaştırılır ve ayrılır; girmeyen N₂ ile H₂ geri döndürülür. Sıvı NH₃\'ün sistemden çekilmesi dengeye nasıl etki eder?', 'Ürün azalınca denge ürünler yönüne kayar', ['Ürün azalınca denge girenler yönüne kayar', 'Denge sabiti sıcaklık sabit kalsa da artar', 'Çekilen ürün dengeyi hiçbir şekilde etkilemez'], 'NH₃ sürekli uzaklaştırıldığında Q, K\'nın altında tutulur; denge yeniden ürün oluşturacak yönde ilerler ve toplam verim yükselir.'),
  ('Buhar reformlama tepkimesi CH₄(g) + H₂O(g) ⇌ CO(g) + 3H₂(g) endotermiktir. H₂ verimini artırmak için hangi koşullar seçilmelidir?', 'Yüksek sıcaklık ve düşük basınç', ['Düşük sıcaklık ve yüksek basınç', 'Düşük sıcaklık ve düşük basınç', 'Yüksek sıcaklık ve yüksek basınç'], 'Endotermik yönü sıcaklık artışı, gaz mol sayısı artan (2 → 4) yönü ise basınç azalması destekler.'),
  ('CO(g) + H₂O(g) ⇌ CO₂(g) + H₂(g) (ΔH < 0) su-gaz kayması dengesinde basıncın artırılması H₂ verimini nasıl etkiler?', 'Etkilemez; mol sayısı iki yanda eşit', ['Artırır, çünkü ürünler daha az yer kaplar', 'Azaltır, çünkü girenler daha yoğun olur', 'Önce azaltır, sonra artırır'], 'Girenlerde 2 mol, ürünlerde 2 mol gaz bulunduğundan basınç denge konumunu kaydırmaz. Verim için ekzotermikliği nedeniyle düşük sıcaklık uygundur.'),
  ('Hb + O₂ ⇌ HbO₂ dengesi düşünülürse, deniz seviyesinden çok yüksek bir dağa çıkan kişide başlangıçta oksijen taşıma kapasitesi neden azalır?', 'O₂ kısmi basıncı düşer, denge sola kayar', ['Hemoglobin miktarı yükseklikte aniden artar', 'Kanın pH\'ı yükseklikte sıfıra iner', 'Denge sabiti soğuk havada belirgin biçimde artar'], 'Yükseklikte O₂\'nin kısmi basıncı azaldığından denge Hb + O₂ yönüne kayar ve HbO₂ oranı düşer. Uzun vadede vücut alyuvar sayısını artırarak uyum sağlar.'),
  ('Karbon monoksit zehirlenmesinde HbO₂ + CO ⇌ HbCO + O₂ dengesi ürünler yönündedir. Hastaya saf (yüksek basınçlı) oksijen solutmanın dengesel mantığı nedir?', 'O₂ artınca denge sola kayar, CO ayrılır', ['CO\'yu doğrudan zararsız CO₂\'ye çevirir', 'Hemoglobin miktarını kısa sürede artırır', 'Denge sabitini ürünler lehine büyütür'], 'Fazla O₂ eklenmesi Le Chatelier ilkesine göre dengeyi sola kaydırır; HbCO azalır, HbO₂ artar.'),
  ('Mağaralarda sarkıt ve dikit oluşumu CaCO₃(k) + CO₂(g) + H₂O ⇌ Ca²⁺ + 2HCO₃⁻ dengesiyle açıklanır. Damlayan sudan CO₂ gazı havaya karışınca hangi olay gerçekleşir?', 'Denge girenler yönüne kayar ve CaCO₃ çöker', ['Denge ürünler yönüne kayar ve CaCO₃ çözünür', 'CaCO₃ derişimi artar ama çökmez', 'Denge sabiti değişir'], 'CO₂ ortamdan çıkınca denge sola kayar; çözünmüş kalsiyum bikarbonat CaCO₃ olarak çökelip sarkıt ve dikitleri oluşturur.'),
  ('298 K\'de bir tepkimenin K değeri 100\'dür. ΔG° yaklaşık kaç kJ/mol\'dür? (ΔG° = −RT ln K, RT = 2,48 kJ/mol, ln 100 = 4,6)', '−11,4', ['+11,40', '−4,6', '−28,6'], 'ΔG° = −2,48 × 4,6 ≈ −11,4 kJ/mol. K > 1 olduğundan standart serbest enerji değişimi negatiftir.'),
  ('Esterleşme (asit + alkol ⇌ ester + su) dengesinde verimi artırmak için tepkime ortamına derişik H₂SO₄ eklenmesi hangi yolla katkı sağlar?', 'Su tutulur, denge ürünlere kayar', ['Alkolü doğrudan esterlere dönüştürür', 'Asidin derişimini sıfıra indirir', 'Denge sabitini kalıcı olarak büyütür'], 'Derişik H₂SO₄ su çekicidir; suyun ortamdan uzaklaşması dengeyi ester oluşumu yönüne kaydırır. (Aynı zamanda katalizördür.)'),
  ('Doymuş NaCl çözeltisine HCl gazı geçirildiğinde katı NaCl çöker. NaCl(k) ⇌ Na⁺ + Cl⁻ dengesi dikkate alındığında bunun nedeni nedir?', 'Cl⁻ artışı dengeyi katı NaCl yönüne kaydırır', ['Na⁺ derişimi aniden azalır', 'Çözeltinin sıcaklığı belirgin biçimde düşer', 'HCl, NaCl\'yi katalizleyerek kristalleştirir'], 'HCl\'den gelen Cl⁻ iyonları ortak iyon etkisiyle dengeyi sola kaydırır; çözeltinin NaCl\'yi tutma kapasitesi düşer ve katı çöker.'),
  ('50 mL 1,0 M HCl ile 50 mL 1,0 M NaOH aynı sıcaklıkta karıştırılıyor ve sıcaklık 6,7 °C artıyor. Çözeltilerin yoğunluğu 1,0 g/mL, özgül ısısı 4,18 J/(g·°C) alınırsa nötrleşme entalpisi yaklaşık kaç kJ/mol\'dür?', '−56', ['+56', '−28', '−112'], 'Toplam kütle 100 g; q = 100 × 4,18 × 6,7 ≈ 2800 J. Tepkimeye giren H⁺ 0,050 mol olduğundan ΔH ≈ −2,8/0,050 = −56 kJ/mol.'),
  ('Bomba kalorimetresi (sabit hacimli, kapalı çelik kap) ile ölçülen ısı doğrudan hangi niceliğe eşittir?', 'İç enerji değişimine (ΔU)', ['Entalpi değişimine (ΔH)', 'Serbest enerji değişimine (ΔG)', 'Entropi değişimine (ΔS)'], 'Sabit hacimde sistem iş yapmaz (w = −PΔV = 0); bu nedenle q_V = ΔU olur. Sabit basınçta ölçülen ısı ise ΔH\'a eşittir.'),
  ('Kapasitesi 9,6 kJ/°C olan bir bomba kalorimetresinde 0,010 mol yakıt tamamen yakıldığında sıcaklık 2,5 °C yükseliyor. Yanma ısısı (kJ/mol, mutlak değer) ne kadardır?', '2400', ['240', '24', '960,0'], 'q = C·ΔT = 9,6 × 2,5 = 24 kJ açığa çıkmıştır. Bu ısı 0,010 mol yakıttan geldiğinden 24/0,010 = 2400 kJ/mol bulunur (ΔU ≈ −2400 kJ/mol).'),
  ('Alüminyumun özgül ısısı yaklaşık 0,90 J/(g·°C), mol kütlesi 27 g/mol\'dür. Molar ısı kapasitesi yaklaşık kaç J/(mol·°C)\'dir?', '24', ['0,033', '30', '243'], 'Molar ısı kapasitesi = özgül ısı × mol kütlesi = 0,90 × 27 ≈ 24 J/(mol·°C). Bu değer birçok katı metal için yaklaşık 25 civarındadır.'),
  ('Kalorimetrede ısı kaybı yaşanması durumunda ölçülen sıcaklık artışı gerçekte olması gerekenden küçük olur. Bu hata, ekzotermik bir tepkimenin hesaplanan entalpi değişiminin mutlak değerini nasıl etkiler?', 'Gerçek değerden küçük bulunur', ['Gerçek değerden büyük bulunur', 'Hiç etkilenmez', 'İşareti değişir'], 'Isı kaybı nedeniyle ΔT küçük ölçülür ve q = mcΔT küçük hesaplanır; böylece |ΔH| gerçekte olduğundan az çıkar.'),
  ('Bir kalorimetrede 50 W gücündeki elektrikli ısıtıcı 60 saniye çalıştırıldığında sıcaklık 0,50 °C artıyor. Kalorimetrenin ısı kapasitesi kaç J/°C\'dir?', '6000', ['3000', '1500', '12 000'], 'Verilen enerji E = P·t = 50 × 60 = 3000 J\'dür. Isı kapasitesi C = 3000 J / 0,50 °C = 6000 J/°C.'),
  ('N₂ + O₂ → 2NO tepkimesinin ΔH = +180 kJ, 2NO + O₂ → 2NO₂ tepkimesinin ΔH = −114 kJ\'dir. Bu verilere göre NO₂(g)\'nin oluşum entalpisi kaç kJ/mol\'dür?', '+33', ['+66', '−33', '−294'], 'İki denklem toplanınca N₂ + 2O₂ → 2NO₂ için ΔH = 180 − 114 = +66 kJ bulunur. Bu 2 mol NO₂ içindir; 1 mol için +33 kJ/mol olur.'),
  ('H₂(g) + ½O₂(g) → H₂O(g) için ΔH = −242 kJ, H₂(g) + ½O₂(g) → H₂O(s) için ΔH = −286 kJ\'dir. Suyun buharlaşma entalpisi (H₂O(s) → H₂O(g)) kaç kJ/mol\'dür?', '+44', ['−44', '+528', '−528'], 'İkinci denklemi ters çevirip birincisiyle toplayınca ΔH = +286 − 242 = +44 kJ/mol bulunur; buharlaşma endotermiktir.'),
  ('Kuvvetli bir asitle kuvvetli bir bazın seyreltik çözeltilerinin nötrleşmesinde ≈ −57 kJ/mol ısı açığa çıkar. CH₃COOH (zayıf asit) ile NaOH nötrleşirken ise açığa çıkan ısı biraz daha azdır. Bunun nedeni nedir?', 'Zayıf asidin iyonlaşması için enerji harcanması', ['Zayıf asidin daha fazla H⁺ vermesi', 'Suyun oluşmaması', 'NaOH\'nin zayıf asitte çözünmemesi'], 'Zayıf asit çözeltide çoğunlukla iyonlaşmamıştır; H⁺ vermesi endotermik bir basamaktır. Bu enerji gereksinimi açığa çıkan nötrleşme ısısının bir kısmını harcar.'),
  ('Kristal örgü yıkılması için gereken enerji +700 kJ/mol, iyonların hidratasyonunda açığa çıkan enerji −740 kJ/mol ise bir tuzun çözünme entalpisi kaç kJ/mol\'dür ve çözünme nasıl olur?', '−40; ekzotermik', ['+40; endotermik', '−1440; ekzotermik', '+1440; endotermik'], 'ΔH_çözünme = ΔH_örgü + ΔH_hidrasyon = +700 + (−740) = −40 kJ/mol; negatif olduğundan ısı açığa çıkar.'),
  ('Aşağıdaki oluşum entalpisi değerlerinden hangisi aynı zamanda başka bir maddenin yanma entalpisine eşittir?', 'H₂O(s)\'nun oluşum entalpisi, H₂(g)\'nin yanma entalpisidir', ['CO(g)\'nun oluşum entalpisi, C(grafit)\'in yanma entalpisidir', 'NH₃(g)\'nın oluşum entalpisi, N₂(g)\'nin yanma entalpisidir', 'CH₄(g)\'nın oluşum entalpisi, CO₂(g)\'nin yanma entalpisidir'], 'H₂ + ½O₂ → H₂O(s) hem suyun oluşumu hem de H₂\'nin yanmasıdır. C\'nin tam yanması ise CO₂ verir, CO değil.'),
  ('Grafit ve elmasın yanma entalpileri sırasıyla −393,5 ve −395,4 kJ/mol\'dür. C(grafit) → C(elmas) dönüşümünün ΔH değeri kaç kJ/mol\'dür?', '+1,9', ['−1,9', '+788,9', '−788,9'], 'ΔH = ΔH_yanma(grafit) − ΔH_yanma(elmas) = −393,5 − (−395,4) = +1,9 kJ/mol. Elmas grafitten enerjice biraz daha zengindir.'),
  ('Eten, katalizör varlığında hidrojenle etana dönüştürülür. Ortalama bağ enerjileri C=C 614, C–C 347, C–H 414 ve H–H 436 kJ/mol ise bu hidrojenleme için ΔH yaklaşık kaç kJ\'dir?', '−125', ['+125', '−1175', '+1050'], 'Kırılan: 614 + 436 = 1050 kJ. Oluşan: 347 + 2(414) = 1175 kJ. ΔH = 1050 − 1175 = −125 kJ.'),
  ('Yıldırım ve motor sıcaklığında havadaki azot ile oksijenden NO oluşur. N≡N 945, O=O 498 ve N=O 631 kJ/mol verilerine göre N₂ + O₂ → 2NO için ΔH yaklaşık nedir?', '+181', ['−181', '+2705', '−1262'], 'Kırılan: 945 + 498 = 1443 kJ. Oluşan: 2(631) = 1262 kJ. ΔH = 1443 − 1262 = +181 kJ; tepkime endotermiktir.'),
  ('Bağ enerjisi verileriyle hesaplanan ΔH değerinin deneysel ΔH değerinden biraz farklı çıkmasının temel nedeni nedir?', 'Tablo ortalama bağ enerjilerine dayanır', ['Bağ enerjisi hiç ısı içermez', 'Tepkime her zaman yalnızca sıvı hâlde gerçekleşir', 'Kırılan bağlar enerjiyi yok eder'], 'Aynı bağın enerjisi bileşikten bileşiğe biraz değişir; tablo ortalama değer verir. Bu nedenle hesap yaklaşık ve gaz hâli için geçerlidir.'),
  ('Amonyum nitratın suda çözünmesi endotermik olduğu hâlde kendiliğinden gerçekleşir. Bunun açıklaması hangisidir?', 'Entropi artışı ΔG\'yi negatif yapar', ['Çözünme sırasında entropi azalır', 'Tepkime ΔH değerini sıfırlar', 'Çözünme termodinamik yasalara aykırı bir olaydır'], 'ΔH pozitif olsa da düzensizlik artışı (ΔS > 0) yeterince büyükse −TΔS terimi ΔG\'yi negatif yapar ve çözünme istemli olur.'),
  ('Suyun donması (ΔH < 0, ΔS < 0) hangi koşulda kendiliğinden gerçekleşir?', 'Düşük sıcaklıkta (0 °C\'nin altında)', ['Her sıcaklıkta', 'Hiçbir sıcaklıkta', 'Yüksek sıcaklıkta (0 °C\'nin üstünde)'], 'ΔG = ΔH − TΔS ifadesinde ΔS < 0 ise −TΔS pozitiftir. T küçükken ΔH baskın olup ΔG negatif olur; donma 0 °C\'nin altında istemlidir.'),
  ('Endotermik (ΔH > 0) ve entropisi azalan (ΔS < 0) bir tepkime için istemlilik hakkında hangisi söylenebilir?', 'Hiçbir sıcaklıkta istemli olmaz', ['Her sıcaklıkta kendiliğinden gerçekleşir', 'Yalnız düşük sıcaklıkta gerçekleşir', 'Yalnız yüksek sıcaklıkta gerçekleşir'], 'ΔG = ΔH − TΔS ifadesinde hem ΔH pozitif hem −TΔS pozitiftir; ΔG her sıcaklıkta pozitif kalır.'),
  ('Sabit sıcaklıkta ΔH = −90 kJ olan ekzotermik bir tepkime 300 K\'de gerçekleşiyor. Çevrenin entropi değişimi (ΔS_çevre = −ΔH/T) kaç J/K olur?', '+300', ['−300', '+270 000', '−0,3'], 'Sistemin verdiği 90 000 J ısı çevreye geçer: ΔS_çevre = 90 000 J / 300 K = +300 J/K. Ekzotermik tepkime çevrenin entropisini artırır.'),
  ('Standart mutlak entropiler SO₂(g) 248, O₂(g) 205 ve SO₃(g) 257 J/(mol·K)\'dır. 2SO₂ + O₂ → 2SO₃ tepkimesinin ΔS° değeri kaç J/K\'dir?', '−187', ['+187', '−701', '+514'], 'ΔS° = ΣS°(ürün) − ΣS°(giren) = 2(257) − [2(248) + 205] = 514 − 701 = −187 J/K. Gaz mol sayısı 3\'ten 2\'ye düştüğü için negatiftir.'),
  ('ΔH = +30 kJ ve ΔS = +100 J/K olan bir tepkime hangi sıcaklıkta kendiliğinden yürümeye başlar?', '300 K\'nin üzerinde', ['300 K\'nin altında', 'Her sıcaklıkta', 'Hiçbir sıcaklıkta'], 'Eşik sıcaklık T = ΔH/ΔS = 30 000/100 = 300 K\'dir. T > 300 K iken ΔG negatif olur.'),
  ('Bir katı ısıtılarak erimiş, daha sonra buharlaştırılmıştır. Entropi değişimi bakımından hangi ifade doğrudur?', 'Buharlaşmadaki artış çok daha büyüktür', ['Erimedeki artış buharlaşmadakinden büyüktür', 'Her iki olayda entropi azalır', 'İkisinde de entropi değişmez'], 'Katı → sıvı geçişinde düzensizlik orta düzeyde, sıvı → gaz geçişinde ise çok büyük ölçüde artar. Bu nedenle ΔS_buharlaşma > ΔS_erime olur.'),
  ('Bir sistem çevreye 100 J ısı veriyor ve üzerinde çevre tarafından 40 J iş yapılıyor. Sistemin iç enerji değişimi kaç J\'dir?', '−60', ['−140', '+60', '+140'], 'q = −100 J ve w = +40 J olduğundan ΔU = q + w = −100 + 40 = −60 J.'),
  ('2 atm sabit dış basınca karşı bir gaz 5 L\'den 8 L\'ye genleşiyor. Gazın yaptığı iş w = −PΔV bağıntısıyla yaklaşık kaç J\'dür? (1 L·atm = 101,3 J)', '−608', ['+608', '−6,00', '−304'], 'w = −PΔV = −(2 atm)(3 L) = −6 L·atm = −6 × 101,3 ≈ −608 J. Gaz iş yaptığı için w negatiftir.'),
  ('Hangi tepkimede sabit sıcaklıkta ΔH ile ΔU yaklaşık aynıdır?', 'H₂(g) + I₂(g) → 2HI(g)', ['2H₂O(s) → 2H₂(g) + O₂(g)', 'CaCO₃(k) → CaO(k) + CO₂(g)', 'N₂(g) + 3H₂(g) → 2NH₃(g)'], 'ΔH − ΔU = ΔnRT olduğundan gaz mol sayısı değişmeyen (Δn = 0) tepkimelerde iki değer eşit olur. Diğer seçeneklerde Δn sıfırdan farklıdır.'),
  ('Bisiklet lastiği pompalanırken pompanın gövdesi ısınır. Bu gözlem, hızla sıkıştırılan gaz için hangi ifadeyle açıklanır?', 'İş iç enerjiyi artırır, sıcaklık yükselir', ['Gaz çevreye ısı vererek hızla soğur ve büzülür', 'İç enerji azalır', 'Gazın entropisi sıfırlanır'], 'Hızlı sıkıştırmada ısı alışverişi ihmal edilebilir (q ≈ 0); gaz üzerinde yapılan iş (w > 0) iç enerjiyi, dolayısıyla sıcaklığı artırır.'),
  ('Endotermik bir tepkimenin potansiyel enerji diyagramında ileri yönün aktifleşme enerjisi (Ea) ile tepkime entalpisi (ΔH) arasında nasıl bir ilişki vardır?', 'Ea, ΔH\'dan büyüktür', ['Ea, ΔH\'dan küçüktür', 'Ea, ΔH\'ye eşit olmak zorundadır', 'Ea her zaman sıfırdır'], 'Endotermik tepkimede ürünler girenlerden yüksek enerjilidir. İlk tepe ürünlerin düzeyinin de üstünde olduğundan Ea(ileri) = ΔH + Ea(geri) > ΔH olur.'),
  ('Endotermik bir tepkimede ürünlerin girenlere göre kararlılığı için hangisi söylenebilir?', 'Enerjice daha yüksek oldukları için ısıl açıdan daha az kararlıdırlar', ['Enerjice daha düşük oldukları için daha kararlıdırlar', 'Kararlılıkları girenlerle aynıdır', 'Kararlılık yalnız katalizöre bağlıdır'], 'Endotermik tepkimede ΔH > 0\'dır; ürünlerin entalpisi girenlerinkinden yüksektir. Bu yüzden ürünler entalpi açısından daha az kararlıdır.'),
  ('Yanma tepkimelerinin çoğunun ekzotermik olmasının temel nedeni nedir?', 'Ürünlerdeki (CO₂, H₂O) bağların girenlerdeki bağlardan daha güçlü olması', ['Ürünlerdeki bağların hiç enerji içermemesi', 'Oksijenin enerji üretmesi', 'Yakıtın kütlesinin artması'], 'Yanmada CO₂ ve H₂O içindeki çok kararlı bağlar oluşur; açığa çıkan bağ enerjisi, kırılan bağlar için harcanandan fazladır ve ısı yayılır.'),
  ('Raylarını kaynaklamak için kullanılan termit tepkimesi (2Al + Fe₂O₃ → Al₂O₃ + 2Fe) demiri eritecek kadar ısı yayar. Bunun başlıca nedeni nedir?', 'Tepkimenin çok ekzotermik olması', ['Tepkimenin endotermik olup ısı soğurması', 'Alüminyumun bağ yapmaması', 'Fe₂O₃\'ün oksijen vermemesi'], 'Al–O bağlarının oluştuğu Al₂O₃ çok kararlıdır; tepkime yaklaşık −850 kJ ısı verir ve sıcaklık yaklaşık 2500 °C\'ye çıkar. Bu nedenle ürün demir erimiş hâlde oluşur.'),
  ('ΔH_yanma değerleri H₂ için −286 kJ/mol (2 g/mol), CH₄ için −890 kJ/mol (16 g/mol), C(grafit) için −394 kJ/mol (12 g/mol) ve C₂H₅OH için −1367 kJ/mol (46 g/mol) olduğuna göre kütle başına en çok ısı veren yakıt hangisidir?', 'H₂', ['CH₄', 'C(grafit)', 'C₂H₅OH'], 'Gram başına ısı: H₂ ≈ 143 kJ/g, CH₄ ≈ 56, C ≈ 33, C₂H₅OH ≈ 30 kJ/g. Hidrojen hafif olduğundan kütle başına en fazla enerjiyi verir.'),
  ('C(grafit) + ½O₂ → CO için ΔH = −111 kJ iken C + O₂ → CO₂ için ΔH = −394 kJ\'dir. Eksik yanmanın daha az ısı vermesinin nedeni nedir?', 'Ürün CO hâlâ yanabilecek enerji (−283 kJ/mol) taşır', ['CO\'nun enerjisi sıfırdır', 'Eksik yanma endotermiktir', 'Oksijen eksikliği C–C bağlarını güçlendirir'], 'CO + ½O₂ → CO₂ için ΔH = −283 kJ\'dir. Karbonun tam yanma enerjisinin bir kısmı CO içinde kimyasal enerji olarak kalır ve açığa çıkmaz.'),
  ('Eşit mollü metan (ΔH_yanma −890 kJ/mol) ve etan (ΔH_yanma −1560 kJ/mol) yakıldığında hangisi daha çok ısı verir ve neden?', 'Etan; mol başına daha çok bağ kırılıp daha çok CO₂ ve H₂O oluştuğu için', ['Metan; daha az karbon içerdiği için', 'İkisi eşit ısı verir', 'Metan; molekül kütlesi daha büyük olduğu için'], 'Etan daha fazla C ve H atomu içerir; yanmada daha çok CO₂ ve H₂O bağı oluşur ve mol başına daha fazla ısı açığa çıkar.'),
  ('100 °C\'deki su buharının neden aynı sıcaklıktaki kaynar sudan çok daha şiddetli yanık oluşturduğu hangi niceliğe dayanır?', 'Buharın yoğuşurken açığa çıkardığı büyük yoğuşma ısısına', ['Buharın kütlesinin daha fazla olmasına', 'Buharın özgül ısısının sıfır olmasına', 'Buharın sıcaklığının daha yüksek olmasına'], 'Buhar cilt üzerinde yoğuşurken gram başına yaklaşık 2260 J ısı verir; bu ısı, kaynar suyun 100 °C\'den soğurken verdiğinden çok daha fazladır.'),
  ('Erime entalpisi +6 kJ/mol, buharlaşma entalpisi +44 kJ/mol olan bir maddenin süblimleşme entalpisi yaklaşık kaç kJ/mol\'dür? (Aynı sıcaklık kabul edilsin.)', '+50', ['+38', '−50', '+264'], 'Süblimleşme, erime ve buharlaşmanın toplamıdır (Hess yasası): 6 + 44 = +50 kJ/mol.'),
  ('Bir besin örneği (2,0 g) kalorimetrede yakılınca 500 g suyun sıcaklığı 14 °C artıyor. Isı kaybı olmadığına göre besinin enerji değeri yaklaşık kaç kJ/g\'dır? (c = 4,184 J/(g·°C))', '14,6', ['29,3', '7,3', '0,0146'], 'q = 500 × 4,184 × 14 = 29 288 J ≈ 29,3 kJ. 2,0 g besin için gram başına ≈ 14,6 kJ/g bulunur.'),
  ('ATP\'nin ADP ve inorganik fosfata hidrolizi için ΔG°′ ≈ −30,5 kJ/mol\'dür. Bu değer hücrede ne anlama gelir?', 'Hidroliz istemlidir ve enerji gerektiren tepkimelere eşlenebilir', ['Hidroliz istemsizdir', 'Hidroliz ısı vermez', 'ATP kararlı bir bileşik olduğundan ayrışmaz'], 'ΔG° < 0 olduğundan hidroliz kendiliğinden yürüyebilir ve açığa çıkan serbest enerji, ΔG > 0 olan biyosentez gibi tepkimeleri yürütmek için kullanılır.'),
  ('Aynı kütleli ve aynı sıcaklıkta suyu buza çevirmek için ortamdan çekilmesi gereken ısı, aynı kütleli suyu 1 °C soğutmak için çekilen ısıdan yaklaşık kaç kat fazladır? (Erime ısısı 334 J/g, c = 4,18 J/(g·°C))', '80', ['4', '334', '0,0125'], 'Aynı m için oran: 334 / 4,18 ≈ 80. Yani 0 °C\'deki suyun donması, 1 °C soğumaya göre yaklaşık 80 kat fazla ısı açığa çıkarır.'),
  ('Bir maddenin sabit güçlü ısıtıcıyla ısıtılması sırasında sıvı hâlde sıcaklığın 20 dakikada 20 °C\'den 60 °C\'ye çıktığı biliniyor. Aynı ısıtıcıyla 2 kat kütlede aynı sıvı aynı sıcaklık aralığında kaç dakikada ısınır?', '40', ['20,0', '10', '80'], 'Gerekli ısı kütleyle doğru orantılıdır (q = mcΔT). Kütle iki katına çıkınca süre de iki katına çıkar: 40 dakika.'),
  ('Birinci mertebeden bir tepkimenin hız sabiti 0,0231 dk⁻¹\'dir. Başlangıçtaki maddenin yüzde kaçı 90 dakika sonra geriye kalır? (t½ = 0,693/k)', '12,5', ['25', '6,250', '50'], 't½ = 0,693/0,0231 = 30 dk\'dır. 90 dk üç yarı ömürdür: (1/2)³ = 1/8 = %12,5.'),
  ('Birinci mertebe bir bozunmanın hız sabiti 0,0693 s⁻¹\'dir. 20 saniye sonra madde miktarı başlangıcın kaçta kaçı olur?', '1/4', ['1/2', '1/8', '1/16'], 't½ = 0,693/0,0693 = 10 s\'dir. 20 s iki yarı ömre eşittir; geriye (1/2)² = 1/4 kalır.'),
  ('Birinci mertebeden bir tepkimede k = 0,10 dk⁻¹\'dir. Derişim 0,80 M\'den 0,20 M\'ye düşene kadar yaklaşık kaç dakika geçer? (ln 4 ≈ 1,39)', '13,9', ['6,90', '27,7', '8,000'], 'ln([A]₀/[A]) = kt → t = ln 4 / 0,10 = 13,9 dk. Bu iki yarı ömürdür (2 × 6,93 dk).'),
  ('İkinci mertebeden bir tepkimede [A]₀ = 0,10 M iken yarı ömür 50 saniyedir. Aynı sıcaklıkta [A]₀ = 0,20 M ile başlanırsa yarı ömür kaç saniye olur?', '25', ['50', '100', '12,5'], 'İkinci mertebede t½ = 1/(k[A]₀) olduğundan başlangıç derişimi iki katına çıkınca yarı ömür yarıya iner: 25 s.'),
  ('Bir tepkimede [A]₀ = 0,10 M iken yarı ömür 40 s, [A]₀ = 0,20 M iken yarı ömür 20 s bulunuyor. Tepkimenin A\'ya göre mertebesi kaçtır?', '2', ['0,0', '1', '3'], 'Yarı ömür başlangıç derişimiyle ters orantılı değişiyor (derişim ×2, yarı ömür ÷2); bu ikinci mertebenin özelliğidir.'),
  ('Bir tepkimede [A] 0, 5 ve 10. dakikalarda sırasıyla 0,40 M, 0,20 M ve 0,10 M ölçülüyor. İlk 5 dakikadaki ortalama hız, ikinci 5 dakikadakinin kaç katıdır?', '2', ['1', '4', '0,5'], 'İlk aralıkta hız 0,20/5 = 0,040 M/dk, ikincisinde 0,10/5 = 0,020 M/dk\'dır. Oran 2\'dir.'),
  ('A\'nın derişimi 0,50 M iken 4,0×10⁻³ M/s, derişimi 0,25 M iken 1,0×10⁻³ M/s hız ölçülmüştür. Bu verilere göre tepkimenin A\'ya göre mertebesi nedir?', '2', ['0', '1', '3'], 'Derişim 0,50 M\'dan 0,25 M\'a yarıya inince hız 4,0×10⁻³\'ten 1,0×10⁻³ M/s\'ye 4 kat azalmıştır: (1/2)ⁿ = 1/4, n = 2. Tepkime A\'ya göre ikinci mertebedendir.'),
  ('Bir tepkimenin hız ifadesinde katı bir giren yer almaz, çünkü katının \'derişimi\' nasıl kabul edilir?', 'Sabit (değişmez) kabul edilir', ['Sıfır', 'Zamanla sürekli artan', 'Ürün derişimine eşit'], 'Saf katının derişimi (birim hacimdeki mol sayısı) sabit kabul edilir; bu nedenle hız ifadesinde katı yer almaz.'),
  ('Bir tepkimenin hız sabiti 25 °C\'de k₁, 35 °C\'de k₂ ise k₂/k₁ oranı için aşağıdakilerden hangisi genellikle beklenir?', '2–3 arasında bir değer', ['Yaklaşık 0,5', 'Tam 1', 'Yaklaşık 100'], 'Birçok tepkimede 10 °C artış hızı kabaca 2–3 kat artırır. Bu, Ea\'nın yaklaşık 50–80 kJ/mol olduğu tepkimeler için geçerli bir kuraldır.'),
  ('C(k) + H₂O(g) ⇌ CO(g) + H₂(g), ΔH > 0 dengesinde kabın hacmi büyütülürse CO miktarı nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce artar, sonra denge sabiti küçülür'], 'Hacim artınca basınç düşer; denge gaz mol sayısı artan ürün tarafına kayar. K değişmez, CO miktarı artar.'),
  ('Fe₃O₄(k) + 4H₂(g) ⇌ 3Fe(k) + 4H₂O(g) dengesinde hacim küçültülürse (sıcaklık sabit) denge konumu için ne söylenebilir?', 'Kaymaz; gaz mol sayısı iki tarafta da 4\'tür', ['Ürünler yönüne kayar', 'Girenler yönüne kayar', 'Katı Fe tamamen tükenir'], 'Gaz mol sayıları eşit olduğundan basınç değişimi dengeyi kaydırmaz; katılar etkili sayılmaz.'),
  ('2SO₃(g) ⇌ 2SO₂(g) + O₂(g) tepkimesi endotermiktir. Sıcaklık artırılınca denge sabiti ve SO₂ miktarı nasıl değişir?', 'İkisi de artar', ['İkisi de azalır', 'K artar, SO₂ azalır', 'K azalır, SO₂ artar'], 'Endotermik ileri yön sıcaklıkla desteklenir; K büyür ve denge ürünler yönüne kayarak SO₂ miktarını artırır.'),
  ('N₂(g) + O₂(g) ⇌ 2NO(g) (ΔH > 0) dengesi için otomobil motorlarındaki çok yüksek sıcaklık nasıl bir sonuç doğurur?', 'NO oluşumu artar', ['NO oluşumu azalır', 'NO miktarı değişmez', 'N₂ tamamen tükenir'], 'Endotermik ileri yön yüksek sıcaklıkla desteklenir; bu yüzden motor içinde NO oluşumu belirginleşir. Basınç etkisizdir (Δn = 0).'),
  ('Açık mavi [Cu(H₂O)₄]²⁺ çözeltisine derişik amonyak eklenince koyu mavi [Cu(NH₃)₄]²⁺ oluşur. Bu gözlem Le Chatelier ilkesine göre nasıl yorumlanır?', 'NH₃ derişimi artınca denge kompleksin oluştuğu yöne kayar', ['Su derişimi azalınca denge sola kayar', 'NH₃ denge sabitini sıfırlar', 'Çözelti seyreldiği için renk koyulaşır'], '[Cu(H₂O)₄]²⁺ + 4NH₃ ⇌ [Cu(NH₃)₄]²⁺ + 4H₂O dengesine NH₃ eklenince denge ürün tarafına kayar ve koyu mavi renk artar.'),
  ('Klorlu sudaki Cl₂ + H₂O ⇌ H⁺ + Cl⁻ + HClO dengesine NaOH eklenirse ne olur?', 'H⁺ tüketildiği için denge ürünler yönüne kayar', ['H⁺ arttığı için denge girenler yönüne kayar', 'Hiçbir şey olmaz', 'Cl₂ gazı katılaşır'], 'OH⁻ iyonları H⁺ ile suyu oluşturup H⁺ derişimini azaltır; denge ürünler yönüne kayar ve çamaşır suyu benzeri hipoklorit oluşumu desteklenir.'),
  ('Atmosferdeki CO₂ artışıyla okyanus suyunda CO₂ + H₂O ⇌ H⁺ + HCO₃⁻ dengesi hangi yöne kayar ve sonuç ne olur?', 'Ürünlere; pH düşer ve kalsiyum karbonatlı kabuklar zarar görür', ['Girenlere; pH yükselir', 'Hiçbir yöne; okyanus etkilenmez', 'Ürünlere; pH yükselir'], 'CO₂ derişimi artınca denge sağa kayar ve H⁺ artar; pH düşer. Asidik su, mercan ve kabuklulardaki CaCO₃\'ı çözerek zarar verir.'),
  ('N₂(g) + 3H₂(g) ⇌ 2NH₃(g) (ΔH < 0) dengesinde sıcaklık artırılıp aynı anda basınç artırılırsa NH₃ verimi hakkında ne denebilir?', 'Etkiler zıt yönlüdür; net sonuç değerlere bağlıdır', ['NH₃ verimi her zaman artar', 'NH₃ verimi her zaman azalır', 'Verim değişmez'], 'Basınç artışı NH₃ yönüne, sıcaklık artışı ise ekzotermik tepkimede girenler yönüne kaydırır. Zıt etkilerde sonuç etkilerin büyüklüğüne bağlıdır.'),
  ('CaCO₃(k) + 2HCl(suda) ⇌ CaCl₂(suda) + H₂O(s) + CO₂(g) tepkimesi açık kapta yürütülüyor. Tepkimenin dengeye ulaşmadan hemen hemen tamamlanmasının nedeni nedir?', 'Ürün CO₂ ortamdan sürekli uzaklaşır', ['Katı CaCO₃ derişimi artar', 'Sıcaklık sürekli düşer', 'HCl katalizör gibi davranır'], 'Açık kapta CO₂ çıkınca ürün derişimi sürekli düşer; Q hep K\'dan küçük kalır ve tepkime ürünler yönünde sürer.'),
  ('A(g) + B(g) ⇌ C(g) dengesinin kurulu olduğu pistonlu bir kapta sıcaklık sabitken piston sıkıştırılırsa hangisi doğrudur?', 'C miktarı artar; K değişmez', ['C miktarı azalır; K azalır', 'C miktarı artar; K artar', 'Denge değişmez; K artar'], 'Girenlerde 2 mol, üründe 1 mol gaz vardır. Basınç artınca denge ürüne kayar ve C artar; K yalnızca sıcaklığa bağlıdır.'),
  ('NO₂(g) için +33 kJ/mol, N₂O₄(g) için +9 kJ/mol oluşum entalpisi verilmiştir. Bir mol N₂O₄\'ün iki mol NO₂\'ye dönüşmesinde entalpi değişimi nedir?', '+57', ['−57', '+24,0', '+75'], 'ΔH = 2(+33) − (+9) = +57 kJ. Tepkime endotermiktir; bu yüzden ısıtınca NO₂ (kahverengi) oranı artar.'),
  ('ΔH°f değerleri CaO(k) −635, CO₂(g) −394 ve CaCO₃(k) −1207 kJ/mol\'dür. CaCO₃ → CaO + CO₂ ayrışmasının ΔH değeri kaç kJ\'dir?', '+178', ['−178', '+1166', '−1166'], 'ΔH = [−635 + (−394)] − (−1207) = −1029 + 1207 = +178 kJ. Kireç taşının ısıtılarak söndürülmemiş kireç elde edilmesi endotermiktir.'),
  ('Ozonun oluşum entalpisi +143 kJ/mol\'dür. 2O₃(g) → 3O₂(g) tepkimesinin ΔH değeri kaç kJ\'dir?', '−286', ['+286', '−143', '+143'], 'O₂\'nin oluşum entalpisi sıfırdır. ΔH = 3(0) − 2(+143) = −286 kJ; ozon O₂\'ye göre enerjice yüksektir ve ayrışması ekzotermiktir.'),
  ('Termit karışımında alüminyum, demir(III) oksiti indirger. Oluşum entalpileri Al₂O₃ için −1676 kJ/mol, Fe₂O₃ için −824 kJ/mol ise 2Al + Fe₂O₃ → Al₂O₃ + 2Fe denklemi için entalpi değişimi kaç kJ\'dir?', '−852', ['+852', '−2500', '−1676'], 'ΔH = [−1676 + 0] − [0 + (−824)] = −852 kJ. Alüminyum oksit demir okside göre çok daha kararlıdır.'),
  ('2Al + Fe₂O₃ → Al₂O₃ + 2Fe termit tepkimesinin ΔH değeri −852 kJ\'dir. 5,6 g demir (Fe = 56 g/mol) oluştuğunda yaklaşık kaç kJ ısı açığa çıkar?', '42,6', ['85,2', '852', '426,0'], '2 mol Fe oluşurken 852 kJ açığa çıkıyorsa 1 mol için 426 kJ, 5,6 g = 0,1 mol Fe için 42,6 kJ ısı açığa çıkar.'),
  ('Bir tepkimenin ΔH değeri tek basamaklı ya da çok basamaklı gerçekleşmesinden bağımsızdır. Aşağıdakilerden hangisi bu nedenle yapılabilir?', 'Doğrudan ölçülemeyen tepkimenin ΔH\'ı diğerlerinden hesaplanır', ['Katalizörle ΔH değeri artırılabilir', 'Hız ifadesi ΔH değerinden yazılabilir', 'Aktifleşme enerjisi de Hess yasasıyla doğrudan bulunabilir'], 'Hess yasası entalpinin durum fonksiyonu olmasına dayanır; ölçülemeyen tepkimeler (örneğin C → CO) bilinen tepkimelerin toplanmasıyla hesaplanır. Ea ve hız bu yolla bulunamaz.'),
  ('A → B tepkimesi için ΔH₁ = +40 kJ, B → C için ΔH₂ = −90 kJ, C → D için ΔH₃ = +10 kJ\'dir. A → D tepkimesinin ΔH değeri ve D → A için ΔH değeri sırasıyla nedir?', '−40 kJ ve +40 kJ', ['+40 kJ ve −40 kJ', '−140 kJ ve +140 kJ', '−60 kJ ve +60 kJ'], 'A → D toplam: 40 − 90 + 10 = −40 kJ. Ters tepkimede işaret değişir: D → A için +40 kJ.'),
  ('Standart oluşum entalpisi pozitif olan bir bileşik için hangisi doğrudur?', 'Elementlerinden oluşması endotermiktir ve elementlere göre enerjice yüksektir', ['Elementlerinden oluşması ekzotermiktir', 'Bileşiğin kararlılığı elementlere eşittir', 'Oluşum entalpisi her zaman sıfırdır'], 'ΔHf > 0 ise bileşiğin entalpisi elementlerinkinden yüksektir. Ancak bu, bileşiğin kinetik olarak kararsız olduğu anlamına gelmez (örneğin NO oda koşullarında kalıcıdır).'),
  ('3Fe(k) + 4H₂O(g) ⇌ Fe₃O₄(k) + 4H₂(g) dengesi için Kc ifadesi hangisidir?', '[H₂]⁴ / [H₂O]⁴', ['[Fe₃O₄][H₂]⁴ /', '[H₂O]⁴ / [H₂]⁴', '[H₂]⁴[Fe₃O₄] / [H₂O]⁴'], 'Saf katıların derişimi sabit kabul edilip denge ifadesine yazılmaz. Yalnız gazların derişimleri kullanılır.'),
  ('I₂(k) ⇌ I₂(g) dengesi için Kc ifadesi nasıl yazılır?', 'Kc = [I₂(g)]', ['Kc = [I₂(g)] / [I₂(k)]', 'Kc = [I₂(k)]', 'Kc = 1'], 'Katı iyotun derişimi sabit olduğundan K\'ya katılır; ifade yalnız gaz iyotun derişimidir.'),
  ('Bir tepkimenin denge sabiti 25 °C\'de 1,0×10⁻⁵, 100 °C\'de 1,0×10⁻² bulunuyor. Bu veriden tepkime hakkında ne söylenebilir?', 'İleri yönde endotermiktir', ['İleri yönde ekzotermiktir', 'ΔH = 0\'dır', 'Gaz mol sayısı artar'], 'Sıcaklık yükselirken K arttığına göre ürünler sıcaklıkla desteklenir; bu endotermik tepkimelerin özelliğidir.'),
  ('Sabit hacimli kapalı bir kapta H₂(g) + I₂(g) ⇌ 2HI(g) dengesinin kurulduğunu göstermek için toplam basıncın izlenmesi neden uygun bir yöntem değildir?', 'Gaz mol sayısı değişmediğinden basınç baştan beri sabit kalır', ['Basınç hiçbir tepkimede ölçülemez', 'HI gazının basıncı sıfırdır', 'Basınç yalnız katılarda değişir'], 'Δn = 0 olduğundan toplam basınç tepkime boyunca değişmez. Denge için I₂\'nin mor renginin şiddeti gibi başka bir nicelik izlenmelidir.'),
  ('3 mol N₂ ve 9 mol H₂ ile başlayan Haber–Bosch tepkimesinin dengesinde 2 mol NH₃ oluşmuştur. Tepkimenin verimi yüzde kaçtır?', '33,3', ['22,20', '66,7', '11,1'], 'Tam dönüşümde 3 mol N₂ ile 6 mol NH₃ oluşurdu. Gerçekte 2 mol oluştuğundan verim 2/6 × 100 = %33,3 olur.'),
  ('N₂(g) + O₂(g) ⇌ 2NO(g) tepkimesinin 25 °C\'de Kc değeri yaklaşık 10⁻³⁰\'dur. Havadaki azot ve oksijen oda sıcaklığında neden belirgin ölçüde NO\'ya dönüşmez?', 'Denge ürünlerin ihmal edilebilir olduğu yöndedir', ['Aktifleşme enerjisi sıfırdır', 'Hava katalizörü yoktur', 'Tepkime ekzotermiktir'], 'Çok küçük K, dengede ürün miktarının hemen hiç olmadığını gösterir. Dönüşüm ancak yıldırım ya da motor gibi çok yüksek sıcaklıklarda anlamlı olur.'),
  ('Kapalı kapta gerçekleşen PCl₅(g) ⇌ PCl₃(g) + Cl₂(g) dengesinin kurulduğunu göstermek için kullanılabilecek en uygun gözlem hangisidir?', 'Toplam basıncın zamanla değişmeyi bırakması', ['Toplam kütlenin artması', 'Kabın sıcaklığının sürekli yükselmesi', 'Kabın rengindeki sürekli koyulaşma'], 'Gaz mol sayısı değiştiği için toplam basınç tepkimeyle birlikte değişir; basınç sabitlenince derişimlerin değişmediği, yani dengenin kurulduğu anlaşılır.'),
  ('Kc değeri ile ilgili hangisi doğrudur?', 'Denklemin katsayıları iki katına çıkarılırsa Kc karesi alınır', ['Katalizörle Kc iki katına çıkar', 'Başlangıç derişimleri artarsa Kc artar', 'Kc derişim birimine bağlı değildir'], 'Denklem n ile çarpılırsa yeni denge sabiti Kcⁿ olur. Katalizör ve başlangıç derişimleri Kc\'yi değiştirmez.'),
  ('Aynı kapta 1 mol N₂O₄ ile başlanan N₂O₄ ⇌ 2NO₂ dengesinde Kp, toplam basıncın artmasıyla nasıl değişir (sıcaklık sabit)?', 'Değişmez; N₂O₄ oranı artar', ['Artar; çünkü ürün tarafı büyür', 'Azalır; çünkü ayrışma durur', 'Sıfır olur; çünkü K sıfırlanır'], 'Kp yalnız sıcaklığa bağlıdır. Basınç artınca denge N₂O₄ yönüne kayar ama K aynı kalır.'),
  ('Sert muzlar kâğıt torbaya konunca düz tezgâha göre daha çabuk olgunlaşır. Bunun nedeni nedir?', 'Etilen birikip olgunlaşmayı hızlandırır', ['Torbanın içinde oksijenin tamamen bitmesi', 'Torbanın ışığı yansıtması', 'Kâğıdın katalizör olması'], 'Etilen olgunlaşma hormonudur; kapalı ortamda derişimi artar ve olgunlaşma tepkimelerini hızlandırır. Derişimin hızı artırmasına örnektir.'),
  ('İlaç firmaları tabletlerin raf ömrünü kısa sürede belirlemek için tabletleri yüksek sıcaklıkta bekletir ve sonuçları oda sıcaklığına taşır. Bu yaklaşımın kinetik dayanağı hangisidir?', 'k\'nın sıcaklıkla Arrhenius\'a göre değişmesi', ['Hız sabitinin sıcaklıktan tamamen bağımsız olması', 'Katalizörün sıcaklıkla artması', 'ΔH\'nın sıcaklıkla sıfırlanması'], 'Yüksek sıcaklıkta bozunma hızlanır. Arrhenius ilişkisiyle k sıcaklıkla bilinen bir bağıntıya uyduğundan oda sıcaklığındaki bozunma hızı tahmin edilir.'),
  ('Mg şeridi seyreltik HCl ile tepkimeye girdiğinde başlangıçta yavaş olan gaz çıkışı zamanla bir süre hızlanabilir. Bunun olası nedeni nedir?', 'Ekzotermik tepkimenin ısıtıp hızlandırması', ['Çözeltideki asit derişiminin zamanla artması', 'Mg yüzeyinin küçülmesi', 'Katalizörün ortamdan kalkması'], 'Ekzotermik tepkimede açığa çıkan ısı sıcaklığı artırır; hız sabiti büyüyerek hız bir süre artabilir. Sonra giren derişimleri azaldıkça hız düşer.'),
  ('Aynı derişimde ve aynı hacimde HCl ve CH₃COOH çözeltileriyle eşit kütle Mg şeritleri tepkimeye sokuluyor. Hangi gözlem beklenir?', 'HCl\'de H₂ daha hızlı çıkar, toplam miktar eşit', ['İki asitte de H₂ çıkış hızı aynıdır', 'CH₃COOH\'te H₂ çıkışı daha hızlıdır, toplamı eşittir', 'HCl\'de hiç H₂ çıkmaz'], 'Güçlü asit HCl\'de [H⁺] daha büyük olduğundan başlangıç hızı yüksektir. Asitlerin mol sayıları eşit olduğundan sonunda toplam H₂ miktarı aynıdır.'),
  ('Bir süt örneği buzdolabında (4 °C) 8 gün bozulmadan kalıyor. Hızı her 10 °C\'lik artışta iki katına çıkan bozulma tepkimeleri için aynı süt 24 °C\'de yaklaşık kaç gün dayanır?', '2', ['4', '16', '1'], '4 °C\'den 24 °C\'ye 20 °C artış, iki kez 10 °C\'dir. Hız 2² = 4 katına çıkar; dayanma süresi 8/4 = 2 gün olur.'),
  ('Soğuk havada çalıştırılan bir aracın ilk dakikalarında katalitik konvertörün zararlı gazları dönüştürme verimi düşüktür. Bunun nedeni nedir?', 'Katalizör yeterince ısınmadığı için hızlar düşüktür', ['Katalizörün soğukta erimesi', 'Egzoz gazının soğukta tamamen sıvıya dönüşmesi ve yüzeyi kaplaması', 'Soğukta ΔH\'ın artması'], 'Konvertörlerdeki katalizörler genellikle birkaç yüz °C\'de etkindir. Soğuk başlangıçta hızlar yavaştır ve kirleticilerin büyük kısmı dönüşmeden çıkar.'),
  ('ΔH = −50 kJ ve ΔS = −100 J/K olan bir tepkimenin istemli olmaktan çıktığı eşik sıcaklık kaç K\'dir? (ΔH ve ΔS sıcaklıktan bağımsız kabul edilsin.)', '500', ['50', '5000', '0,5'], 'ΔG = 0 için T = ΔH/ΔS = (−50 000)/(−100) = 500 K\'dir. T > 500 K olunca −TΔS terimi baskın olur ve ΔG pozitifleşir.'),
  ('H₂O(s) → H₂O(g) için ΔH = +44 kJ/mol ve ΔS = +119 J/(mol·K)\'dir. Standart koşullarda buharlaşmanın istemli hâle geçtiği sıcaklık yaklaşık kaç K\'dir?', '370', ['25', '44,0', '119'], 'ΔG = 0 koşulunda T = 44 000/119 ≈ 370 K\'dir. Bu değer suyun normal kaynama noktasına (373 K) yakındır.'),
  ('Bir tepkimenin ΔG° değeri −2,0×10² kJ ise sabit sıcaklık ve basınçta bu tepkimeden elde edilebilecek en fazla yararlı iş ne kadardır?', '200 kJ', ['100 kJ', '0 kJ', '400,0 kJ'], 'Sabit T ve P\'de elde edilebilecek maksimum yararlı iş (genleşme dışındaki iş) |ΔG| değerine eşittir; burada 200 kJ\'dir.'),
  ('−5 °C\'de bir buz parçasının kendiliğinden erimesi için ΔG nasıl bir işaret taşır?', 'Pozitif; erime bu sıcaklıkta istemsizdir', ['Negatif; erime istemlidir', 'Sıfır; denge hâlindedir', 'İşaret belirlenemez'], 'Erime ΔH > 0 ve ΔS > 0 olduğundan istemlilik T > 273 K koşulunda sağlanır. −5 °C\'de ΔG > 0\'dır, buz erimez.'),
  ('ΔG₁ = +30 kJ olan bir tepkime, ΔG₂ = −50 kJ olan ATP hidrolizi ile eşlenirse toplam tepkimenin ΔG değeri ve durumu ne olur?', '−20 kJ; istemli', ['+80 kJ; istemsiz', '−80 kJ; istemli', '+20 kJ; istemsiz'], 'Eşlenen tepkimelerde ΔG değerleri toplanır: +30 + (−50) = −20 kJ. Toplam negatif olduğundan süreç istemli yürür.'),
  ('Boltzmann\'a göre entropi S = k·ln W bağıntısıyla verilir. Burada W neyi ifade eder?', 'Sistemin aynı makroskopik durumu veren mikro durum sayısını', ['Sistemin yaptığı işi', 'Sistemin toplam ısısını', 'Sistemin kütlesini'], 'W, belirli bir makro durumun olası mikro durum sayısıdır. Bu sayı arttıkça entropi artar.'),
  ('Isı kapasitesi 100 J/°C olan bir kalorimetrede 100 g su kullanılıyor ve bir tepkime sırasında sıcaklık 5,0 °C artıyor. Tepkimenin açığa çıkardığı toplam ısı yaklaşık kaç J\'dir? (c_su = 4,18 J/(g·°C))', '2590', ['2090', '500,0', '418'], 'Su 100 × 4,18 × 5,0 = 2090 J, kalorimetre 100 × 5,0 = 500 J ısı alır. Toplam 2590 J\'dür.'),
  ('Nötrleşme deneyinde aynı derişimlerde ve oranda asit ile baz hacimleri yarıya indirilirse sıcaklık artışı ΔT için ne söylenebilir?', 'Değişmez; hem açığa çıkan ısı hem ısınan kütle yarıya iner', ['Yarıya iner', 'İki katına çıkar', 'Dörtte birine iner'], 'Mol sayısı yarıya inince ısı da yarıya iner; fakat ısınan çözelti kütlesi de yarıya indiğinden q/(mc) oranı, yani ΔT değişmez.'),
  ('Bir kalorimetre sabiti, ΔH\'ı bilinen bir tepkimeyle belirleniyor. 0,010 mol maddenin ΔH = −40 kJ/mol olan çözünmesi sırasında sıcaklık 0,80 °C artarsa kalorimetre (içindeki su dahil) ısı kapasitesi kaç J/°C\'dir?', '500', ['400', '32,0', '50'], 'Açığa çıkan ısı 0,010 × 40 000 = 400 J\'dür. C = 400/0,80 = 500 J/°C.'),
  ('Aynı miktarda ısı elde etmek için metan (ΔH_yanma = −890 kJ/mol) ve grafit karbon (ΔH_yanma = −394 kJ/mol) yakıldığında, açığa çıkan CO₂ miktarı bakımından hangisi doğrudur?', 'Metan, aynı ısı için yaklaşık 2,3 kat daha az CO₂ üretir', ['Karbon, aynı ısı için daha az CO₂ üretir', 'İkisi eşit CO₂ üretir', 'Metan daha çok CO₂ üretir'], 'Her mol yakıt 1 mol CO₂ verir. Isı başına CO₂: metan 1/890, karbon 1/394 mol/kJ\'dir; metan yaklaşık 890/394 ≈ 2,3 kat daha az CO₂ üretir.'),
  ('Hidrojen yakıtı kütle başına çok yüksek enerji verir. Buna rağmen taşıtlarda depolanması güç olmasının kimyasal nedeni nedir?', 'Gaz hâlinde hacim başına enerji yoğunluğunun düşük olması', ['Hidrojenin hiç yanmaması', 'Yanma ürününün zehirli olması', 'Hidrojenin ağır bir element olması'], 'Birim kütlede ısısı yüksek olsa da H₂ gazı çok hafif ve geniş hacimlidir; yüksek basınç ya da düşük sıcaklıkla sıkıştırılması gerekir.'),
  ('Nitrogliserin gibi patlayıcıların etkisini artıran ortak özellikler hangileridir?', 'Çok ekzotermik, çok hızlı ve çok miktarda gaz oluşturan ayrışma', ['Endotermik ve yavaş ayrışma', 'Hiç gaz oluşturmayan ayrışma', 'Entropiyi azaltan yavaş tepkime'], 'Patlamada ısı açığa çıkması, tepkimenin son derece hızlı olması ve katı/sıvıdan çok hacimli gaz oluşması basıncı ani biçimde yükseltir.'),
  ('Gaz taneciklerinin çarpışma sayısı sıcaklıkla yalnızca √T ile artar (10 °C artışta yaklaşık %2). Hızın buna rağmen yaklaşık iki katına çıkmasının nedeni nedir?', 'Aktifleşme enerjisini aşan taneciklerin oranının büyük artması', ['Taneciklerin kütlesinin artması', 'Aktifleşme enerjisinin azalması', 'Tüm çarpışmaların etkin olması'], 'Çarpışma sıklığındaki küçük artışa karşılık e^(−Ea/RT) terimi çok daha duyarlıdır; eşik enerjiyi aşan tanecik oranı belirgin biçimde artar.'),
  ('Aynı ortamda iki farklı tepkimenin hız sabitleri sıcaklıkla ln k = ln A − Ea/RT\'ye uyuyor. A değerleri çok farklı ve Ea değerleri eşitse hangisi söylenebilir?', 'A büyük olanın hız sabiti her sıcaklıkta daha büyüktür', ['Hız sabitleri eşittir', 'A küçük olanın hız sabiti daha büyüktür', 'Ea eşitse A önemsizdir'], 'Ea\'ları eşit olduğundan e^(−Ea/RT) çarpanı aynıdır; k = A·e^(−Ea/RT) olduğu için A büyük olanın k\'sı daha büyüktür.'),
  ('Haber–Bosch reaktöründe tek geçişte N₂ ve H₂\'nin yalnız yaklaşık %10–20\'si NH₃\'e dönüşür. Sürecin toplam veriminin çok yüksek olması hangi uygulamaya bağlıdır?', 'NH₃\'ün sıvılaştırılarak ayrılması ve girenlerin reaktöre geri döndürülmesi', ['Reaktör sıcaklığının sürekli düşürülmesi', 'Katalizörün her turda değiştirilmesi', 'Basıncın sıfıra indirilmesi'], 'Dengeye ulaşan gaz karışımı soğutulup NH₃ sıvı olarak çekilir, artan N₂ ve H₂ yeniden reaktöre verilir; böylece toplam dönüşüm artar.'),
  ('Solvay yönteminde NaCl + NH₃ + CO₂ + H₂O ⇌ NaHCO₃ + NH₄Cl dengesinde ürünlerin oluşmasını kolaylaştıran etken nedir?', 'NaHCO₃\'ın az çözünür olup çökelerek ortamdan çekilmesi', ['NH₄Cl\'ün katı olarak çökmesi', 'CO₂\'nin ortamdan uzaklaşması', 'NaCl derişiminin sıfırlanması'], 'Soğuk derişik çözeltide NaHCO₃ az çözündüğünden çöker; ürün derişimi düşük kalır ve denge ürünler yönünde ilerler.'),
  ('İdeal bir gazın sabit basınçtaki molar ısı kapasitesi (Cp) ile sabit hacimdeki molar ısı kapasitesi (Cv) arasındaki fark nedir?', 'Cp − Cv = R', ['Cp − Cv = 2R', 'Cp − Cv = 0', 'Cp − Cv = R/2'], 'Sabit basınçta ısıtılan gaz genleşip iş yaptığı için aynı sıcaklık artışına daha çok ısı gerekir. İdeal gazda Cp − Cv = R\'dir.'),
  ('N₂(g) + 3H₂(g) ⇌ 2NH₃(g) dengesinde 1 L\'lik kapta N₂ 0,50 M, H₂ 1,5 M ve NH₃ 0,75 M\'dir. Reaksiyon bölümü Q, sıcaklık sabitken yalnız H₂ ilavesiyle derişimi 2,0 M\'ye çıkarılınca nasıl değişir?', 'Q azalır; denge ürünlere kayar', ['Q artar; denge girenlere kayar', 'Q değişmez', 'Q sıfır olur'], 'Q = [NH₃]²/([N₂][H₂]³) paydadaki H₂ derişimi büyüyünce Q küçülür. Q < K olduğundan sistem ürün oluşturarak dengeye döner.'),
  ('Bir kapta A(g) ⇌ 2B(g) için Kc = 0,50 M\'dir. Bir anda [A] = 1,0 M ve [B] = 1,0 M ise sistem nasıl davranır?', 'Q = 1,0 > Kc olduğundan geriye (A oluşumu yönüne) ilerler', ['Q = 1,0 < Kc olduğundan ileri ilerler', 'Q = Kc olduğundan dengededir', 'Q hesaplanamaz'], 'Q = [B]²/[A] = 1,0 M\'dir ve Kc\'den büyüktür. Ürün fazlalığı olduğundan denge sola kayarak A artar.'),
  ('Denge hâlindeki bir kapalı sisteme aynı sıcaklıkta yalnız ürün eklendiğinde hız grafiğine bakan bir öğrenci hangi yorumu yapar?', 'Geri hız anlık artar, sonra ileri hız artar ve yeni denge kurulur', ['Her iki hız eşit kalır', 'İleri hız hiç değişmez, geri hız sıfırlanır', 'Her iki hız sıfırlanır'], 'Ürün eklenince geri tepkime hızı artar ve girenler oluşur. Girenler biriktikçe ileri hız da yükselir ve iki hız yeniden eşitlenir.'),
  ('Kenarı 2 cm olan bir katı küp, kenarı 1 cm olan 8 eş küpe bölünüyor. Toplam yüzey alanı ilk durumun kaç katı olur?', '2', ['4', '8', '1,0'], 'İlk küpün yüzey alanı 6 × 4 = 24 cm²\'dir. 8 küçük küpün toplamı 8 × 6 = 48 cm²\'dir; yüzey alanı 2 katına çıkar ve katı ile tepkime hızı artar.'),
  ('İyot saat deneyinde belirli bir anda çözeltinin birdenbire maviye dönmesi için geçen süre ölçülür. Bu süre ile tepkime hızı arasında nasıl bir ilişki vardır?', 'Süre kısaldıkça hız artar', ['Süre uzadıkça hız artar', 'Süreyle hız arasında ilişki yoktur', 'Süre hızın karesine eşittir'], 'Renk değişimi için gereken belirli bir miktar dönüşüm tamamlanır. Aynı dönüşüm kısa sürede oluyorsa ortalama hız büyüktür.'),
  ('Üst atmosferde NO + O₃ → NO₂ + O₂ ve NO₂ + O → NO + O₂ basamakları birlikte işleyerek ozonu yıkar. Bu mekanizmada NO ve NO₂\'nin rolleri nedir?', 'NO katalizör, NO₂ ara üründür', ['NO ara ürün, NO₂ katalizördür', 'İkisi de nihai üründür', 'İkisi de nihai girendir'], 'NO ilk basamakta harcanıp ikincisinde yeniden oluşur (katalizör); NO₂ önce oluşur sonra harcanır (ara ürün).'),
  ('İçilen etil alkolün karaciğerde yaklaşık sabit bir hızla (saatte yaklaşık 7–10 g) metabolize edilmesi hangi kinetik davranışla açıklanır?', 'Enzim doygunluğu nedeniyle sıfırıncı mertebe davranış', ['Birinci mertebe davranış', 'İkinci mertebe davranış', 'Alkolün hiç katalizlenmemesi'], 'Alkol dehidrogenaz enzimi doygun hâlde çalışır; substrat derişimi artsa da hız sabit kalır. Bu sıfırıncı mertebe kinetiğidir.'),
  ('A → B → C ardışık tepkimesinde ara ürün B\'nin derişimi zamanla nasıl değişir?', 'Önce artar, bir maksimumdan geçip sonra azalır', ['Sürekli artar', 'Sürekli azalır', 'Hep sabit kalır'], 'B, A\'dan oluşurken C\'ye de dönüşür. Başlangıçta oluşum hızı baskın olduğundan artar; A tükendikçe C\'ye dönüşüm baskın olur ve B azalır.'),
  ('Kenar uzunluğu 1 cm olan bir metal küp, kenar uzunluğu 1 mm olan 1000 küçük küpe ayrılıyor. Toplam yüzey alanı kaç kat artar?', '10', ['100', '1000', '1'], 'İlk durum 6 cm²\'dir. 1000 küp × 6 × (0,1 cm)² = 60 cm²\'dir; yüzey alanı 10 katına çıkar.'),
  ('Birinci mertebeden bir tepkimenin t = 0\'da hızı 8,0×10⁻³ M/s\'dir. Bir yarı ömür sonra hız kaç M/s olur?', '4,0×10⁻³', ['8,0×10⁻³', '2,0×10⁻³', '1,60×10⁻²'], 'Birinci mertebede hız derişimle orantılıdır; bir yarı ömürde derişim yarıya, dolayısıyla hız da yarıya iner.'),
  ('Etanolün yanmasından elde edilen 683,5 kJ ısının tamamı 2,0 kg suyu ısıtmak için kullanılırsa suyun sıcaklığı yaklaşık kaç °C artar? (c = 4,18 J/(g·°C))', '82', ['41', '164', '8,2'], 'ΔT = q/(mc) = 683 500 / (2000 × 4,18) ≈ 81,8 °C ≈ 82 °C.'),
  ('ΔH°f değerleri H₂O(g) −242 ve CO(g) −111 kJ/mol\'dür. Su gazı elde edilen C(k) + H₂O(g) → CO(g) + H₂(g) tepkimesinin ΔH değeri kaç kJ\'dir?', '+131', ['−131', '−353', '+353'], 'ΔH = [−111 + 0] − [0 + (−242)] = +131 kJ. Tepkime endotermiktir; bu nedenle sürekli ısı verilmesi gerekir.'),
  ('Kömürden su gazı üretiminde kızgın karbona su buharı gönderilir. Oluşum entalpileri H₂O(g) için −242, CO(g) için −111 kJ/mol ise C + H₂O(g) → CO + H₂ için entalpi değişimi nedir?', '+131', ['−131', '+353', '−90'], 'H₂ ve C(grafit) element olduğundan oluşum entalpileri sıfırdır. ΔH = [−111 + 0] − [0 + (−242)] = +131 kJ (endotermik).'),
  ('Metanol sentezinde CO(g) + 2H₂(g) → CH₃OH(g) tepkimesi gerçekleşir. CO için −111, CH₃OH(g) için −201 kJ/mol oluşum entalpisi verildiğine göre bu sentezin ısı değişimi kaç kJ\'dir?', '−90', ['+90', '−312', '+312'], 'H₂\'nin oluşum entalpisi sıfırdır. ΔH = −201 − (−111 + 0) = −90 kJ (ekzotermik).'),
  ('Doğal gazdan hidrojen üretiminde CH₄ + H₂O(g) → CO + 3H₂ tepkimesi kullanılır. Oluşum entalpileri CH₄ −75, H₂O(g) −242, CO −111 kJ/mol ise bu tepkimenin entalpi değişimi nedir?', '+206', ['−206', '+1369', '−1369'], 'ΔH = [−111 + 3(0)] − [−75 + (−242)] = −111 + 317 = +206 kJ (endotermik).'),
  ('2H₂(g) + O₂(g) → 2H₂O(g) için ΔH = −484 kJ, 2H₂(g) + O₂(g) → 2H₂O(s) için ΔH = −572 kJ\'dir. Aynı miktar hidrojenin sıvı yerine buhar suya yanması ne kadar daha az ısı verir?', '88 kJ', ['44 kJ', '572 kJ', '1056 kJ'], 'Fark 572 − 484 = 88 kJ\'dir; bu, 2 mol suyun buharlaşma ısısıdır (2 × 44 kJ).'),
  ('NaCl(k) → Na⁺(suda) + Cl⁻(suda) çözünme olayı için sistemin entropi değişimi hakkında genel olarak ne söylenebilir?', 'Düzenli kristal örgü dağıldığı için ΔS pozitiftir', ['Iyonlar düzenlendiği için ΔS negatiftir', 'ΔS tam olarak sıfırdır', 'ΔS kesinlikle belirlenemez'], 'Katı kristalin düzeni bozulup iyonlar çözeltide serbest dolaşır; düzensizlik artar. (Suyun iyonlar çevresinde düzenlenmesi küçük bir azalma getirir.)'),
  ('C(k) + O₂(g) → CO₂(g) tepkimesinde entropi değişiminin mutlak değeri neden küçüktür?', 'Gaz mol sayısı girenlerde ve ürünlerde aynıdır', ['Katı karbon hiç entropiye sahip değildir', 'CO₂ katı hâldedir', 'Tepkime çok yavaştır'], 'Gaz mol sayısı değişmediğinden ΔS sıfıra yakındır; küçük farklar gazların molekül karmaşıklığından gelir.'),
  ('2C(k) + O₂(g) → 2CO(g) tepkimesi için entropi değişimi hakkında ne söylenebilir?', 'ΔS pozitiftir; gaz mol sayısı 1\'den 2\'ye çıkar', ['ΔS negatiftir; katı oluşur', 'ΔS sıfırdır', 'Işık ile belirlenir'], 'Girenlerde 1 mol gaz, ürünlerde 2 mol gaz bulunur; gaz mol sayısındaki artış entropiyi yükseltir. Bu özelliği yüksek sıcaklıkta tepkimeyi istemli kılar.'),
  ('Kuru buzun (katı CO₂) 1 atm\'de süblimleşmesi için ΔH = +25,2 kJ/mol ve ΔS = +129 J/(mol·K)\'dir. Süblimleşmenin istemli olduğu sıcaklık yaklaşık kaç K\'in üzeridir?', '195', ['25', '129,0', '298'], 'T = ΔH/ΔS = 25 200 / 129 ≈ 195 K (yaklaşık −78 °C). Bu sıcaklığın üstünde kuru buz süblimleşir.'),
  ('Etil alkolün normal kaynama noktası 351,5 K ve buharlaşma entalpisi 38,6 kJ/mol\'dür. Buharlaşma entropisi yaklaşık kaç J/(mol·K)\'dir?', '110', ['38,6', '351,5', '13 568'], 'Kaynama noktasında ΔG = 0\'dır; ΔS = ΔH/T = 38 600 / 351,5 ≈ 110 J/(mol·K).'),
  ('Buzun oda sıcaklığında (25 °C) erimesi için aşağıdakilerden hangisi söylenebilir?', 'Endotermiktir ancak entropi artışı nedeniyle istemlidir', ['Ekzotermiktir ve istemlidir', 'Endotermik olduğu için istemsizdir', 'Entropi azaldığı için istemlidir'], 'Erime ΔH > 0 olmasına karşın ΔS > 0\'dır. 273 K\'in üstünde −TΔS terimi ΔH\'ı yener ve ΔG < 0 olur.'),
  ('Canlı organizmalar düzenli yapılar kurar, yani yerel entropiyi azaltır. Bu durum termodinamiğin ikinci yasasıyla nasıl bağdaşır?', 'Çevreye ısı ve atık vererek evrenin toplam entropisi artar', ['Canlılar için yasa geçerli değildir', 'Canlı sistemlerde entropi sıfırdır', 'Yasa yalnız gazlar için geçerlidir'], 'Canlılar çevreden enerji alıp ısı ve basit moleküller verir. Çevrenin entropisindeki artış, organizmadaki düzenlenmeyi aşar; ΔS_evren > 0\'dır.'),
  ('Ekzotermik bir tepkime düşük sıcaklıkta kendiliğinden gerçekleşip yüksek sıcaklıkta gerçekleşmiyorsa tepkime için ΔS işareti nedir?', 'Negatif', ['Pozitif', 'Sıfır', 'Belirlenemez'], 'ΔH < 0 olup yüksek sıcaklıkta istemsizleşme, −TΔS teriminin pozitif ve büyük olmasıyla olur; bu yalnız ΔS < 0 iken mümkündür.'),
  ('Femtosaniye ölçeğinde lazer atımlarıyla tepkimeler sırasındaki geçiş hâllerini gözlemleyerek 1999 Nobel Kimya Ödülü\'nü alan bilim insanı kimdir?', 'Ahmed Zewail', ['Gerhard Ertl', 'Ernest Rutherford', 'Marie Curie'], 'Zewail, bağların kırılıp oluştuğu çok kısa süreli geçiş hâllerini femtosaniye spektroskopisiyle izleyerek \'femtokimya\' alanını kurmuştur.'),
  ('Katı yüzeylerdeki kimyasal süreçleri, özellikle demir yüzeyinde amonyak sentezinin ayrıntılı mekanizmasını açıklayarak 2007 Nobel Kimya Ödülü\'nü alan bilim insanı kimdir?', 'Gerhard Ertl', ['Ahmed Zewail', 'Fritz Haber', 'Linus Pauling'], 'Ertl, N₂ ve H₂\'nin demir yüzeyinde adım adım tepkimeye girişini inceleyerek yüzey kimyasını yeni bir düzeye taşımıştır.'),
  ('Bomba kalorimetresini geliştirerek yanma ısılarının doğru ölçülmesinde öncü olan Fransız kimyacı kimdir?', 'Marcellin Berthelot', ['Louis Pasteur', 'Henri Becquerel', 'Antoine Lavoisier'], 'Berthelot, sabit hacimli kapalı bir kapta maddelerin oksijenle yakılması esasına dayanan bomba kalorimetresini kullanarak termokimyanın deneysel temelini oluşturmuştur.'),
  ('Birinci mertebeden bir bozunmada başlangıç madde miktarının yüzde kaçı 2,5 yarı ömür sonra geriye kalır? (2^(−2,5) ≈ 0,177)', '17,7', ['12,50', '25', '8,80'], 'Kalan oran (1/2)^2,5 = 0,177\'dir; yani yaklaşık %17,7 kalır. İki yarı ömürde %25, üçünde %12,5 kalır; 2,5 bunların arasındadır.'),
  ('Sıfırıncı mertebeden bir tepkimede k = 0,010 M/s ve [A]₀ = 0,80 M\'dir. [A] değerinin 0,20 M\'ye inmesi kaç saniye sürer?', '60', ['20,0', '80', '40'], '[A] = [A]₀ − kt → 0,20 = 0,80 − 0,010t ve t = 60 s.'),
  ('2A → ürün gibi aynı tür tanecikler arasındaki çarpışmaya dayalı bir gaz tepkimesinde A\'nın derişimi iki katına çıkarılırsa birim zamandaki çarpışma sayısı kaç katına çıkar?', '4', ['2', '8', '1,0'], 'Aynı tür iki tanecik arasındaki çarpışma sıklığı derişimin karesiyle orantılıdır; derişim iki katına çıkınca çarpışma sayısı dört katına çıkar.'),
  ('Ester hidrolizi seyreltik HCl çözeltisiyle hızlanır. Tepkime sonunda H⁺ iyonlarının miktarıyla ilgili hangisi doğrudur?', 'H⁺ iyonu katalizör olduğundan miktarı değişmez', ['H⁺ tamamen harcanır', 'H⁺ miktarı iki katına çıkar', 'H⁺ ürüne dönüşür ve geri gelmez'], 'Asit, mekanizmada geçici olarak ester oksijenine bağlanıp tepkimeyi kolaylaştırır; sonunda yeniden serbest kalır. Bu homojen katalizdir.'),
  ('Tüm enzimlerin protein olduğu düşünülürken RNA\'dan oluşan ve tepkimeleri hızlandırabilen ribozimlerin bulunması hangi sonuca yol açmıştır?', 'Biyolojik katalizörlerin yalnız protein olmadığı anlaşılmıştır', ['Katalizörlerin tepkimede harcandığı kanıtlanmıştır', 'Enzimlerin sıcaklıktan etkilenmediği anlaşılmıştır', 'RNA\'nın ΔG\'yi değiştirdiği kanıtlanmıştır'], 'Ribozimler (Cech ve Altman\'ın 1989 Nobel çalışması) RNA\'nın da katalitik etki gösterebildiğini göstermiştir.'),
  ('Kendini temizleyen camlarda kullanılan TiO₂ kaplama hangi ilkeye göre çalışır?', 'UV ışığıyla etkinleşip organik kirleri parçalar', ['Cam yüzeyini ısıtarak kirleri buharlaştırıp uzaklaştırması', 'Yüzeydeki serbest enerji değerini sürekli değiştirmesi', 'Kirleri mıknatıs gibi çekmesi'], 'TiO₂, UV ışığı altında yüzeyinde kuvvetli yükseltgen türler oluşturarak organik kirleri parçalar. Işıkla etkinleşen katalizörlere fotokatalizör denir.'),
  ('Tepkime hızını azaltan inhibitörler (negatif katalizörler) için hangisi doğrudur?', 'Yüksek enerjili yol sunar ya da radikalleri tüketir', ['Aktifleşme enerjisini azaltıp yeni bir yol sunar', 'Ürünleri daha kararlı yaparak denge sabitini büyütür', 'Tepkime ΔH değerini artırarak ısıyı çevreye yayar'], 'İnhibitör, tepkime hızını düşüren maddedir; ya yüksek enerjili bir yol sağlar ya da zincir taşıyan radikalleri tüketir.'),
  ('Haber–Bosch katalizöründe demire küçük miktarlarda K₂O ve Al₂O₃ eklenir. Bu katkı maddelerine ne ad verilir?', 'Promotör', ['İnhibitör', 'Çözücü', 'Tampon'], 'Promotörler katalizörün etkinliğini ya da dayanıklılığını artıran katkılardır; kendileri tek başına etkin olmayabilir.'),
  ('Enzimlerin tepkime hızını milyonlarca kat artırabilmesi hangi kinetik gerekçeye dayanır?', 'Aktifleşme enerjisini önemli ölçüde düşürmeleri', ['Girenlerin kütlesini artırmaları', 'Tepkime entalpisini sıfırlamaları', 'Ürün miktarını artırmaları'], 'Enzimler substratı aktif merkezde bağlayarak geçiş hâlini kararlı kılar; Ea düşer ve hız sabiti çok büyür. ΔH ve denge konumu değişmez.'),
  ('Gaz tepkimelerinde derişim yerine kısmi basınç kullanılarak ikinci mertebeden r = k_p·P_A² biçiminde yazılırsa k_p\'nin birimi nedir?', 'atm⁻¹ s⁻¹', ['atm s⁻¹', 's⁻¹', 'atm⁻² s⁻¹'], 'r atm/s, P_A² atm² olduğundan k_p = (atm/s)/atm² = atm⁻¹ s⁻¹ olur.'),
  ('Stokiyometrik karışımla (1 mol N₂ + 3 mol H₂) başlayan amonyak sentezinde 0,20 mol N₂ tepkimeye girerse dengede toplam gazın mol kesri olarak NH₃ yüzde kaçtır?', '11,1', ['10', '20,00', '5'], 'N₂ 0,8; H₂ 2,4; NH₃ 0,4 mol\'dür; toplam 3,6 mol. NH₃ mol kesri 0,4/3,6 ≈ %11,1.'),
  ('Sabit hacimli kapta yalnız N₂O₄ ile başlanıp N₂O₄ ⇌ 2NO₂ dengesi kuruluyor. Aynı sıcaklıkta denge basıncı başlangıç basıncının 1,4 katı ise N₂O₄\'ün yüzde kaçı ayrışmıştır?', '40', ['14', '28', '70,0'], 'Δn = +1 olduğundan n_toplam/n₀ = 1 + α = 1,4 ve α = 0,40\'tır; yani %40 ayrışma olmuştur.'),
  ('Q < K olan bir sistem için serbest enerji değişimi ΔG = RT ln(Q/K) bağıntısına göre hangi işaretlidir?', 'Negatif', ['Pozitif', 'Sıfır', 'Belirsiz'], 'Q < K ise Q/K < 1 ve ln(Q/K) < 0\'dır; ΔG negatif olur, yani ürün oluşumu yönündeki süreç kendiliğinden gerçekleşir.'),
  ('Isı alışverişinin olmadığı (ΔH = 0) bir tepkimenin denge sabiti sıcaklık değişince nasıl davranır?', 'Yaklaşık değişmez', ['Hep artar', 'Hep azalır', 'İkiye katlanır'], 'van\'t Hoff bağıntısına göre d ln K/dT = ΔH/RT² olduğundan ΔH = 0 ise K sıcaklıkla değişmez; denge konumu entropi ile belirlenir.'),
  ('CaCO₃(k) ⇌ CaO(k) + CO₂(g) dengesinde sıcaklık yükseltilirse denge CO₂ basıncı nasıl değişir?', 'Artar; tepkime endotermiktir', ['Azalır; tepkime ekzotermiktir', 'Değişmez; katılar etkilemez', 'Sıfır olur'], 'Tepkime endotermik olduğundan sıcaklıkla Kp = P(CO₂) artar. Bu nedenle kireç ocakları çok yüksek sıcaklıkta çalıştırılır.'),
  ('Kapalı bir şişedeki gazlı içecekte CO₂(g) ⇌ CO₂(suda) dengesi vardır. İçecek buzdolabında soğutulursa çözünmüş CO₂ miktarı nasıl değişir?', 'Artar; çözünme ekzotermiktir', ['Azalır; çözünme endotermiktir', 'Değişmez', 'Önce azalır sonra artar'], 'Gazların sudaki çözünmesi ekzotermiktir; sıcaklık düşünce denge çözünme yönüne kayar. Bu yüzden soğuk içecekler daha çok gaz tutar.'),
  ('\'Katalizör eklenirse denge ürünler yönüne kayar ve ürün miktarı artar\' savı neden yanlıştır?', 'Katalizör iki yönü de eşit hızlandırır, bileşim değişmez', ['Katalizör çoğunlukla ürünleri bozup dengeyi tersine çevirir', 'Katalizör yalnız girenleri hızlandırır', 'Katalizör Kc değerini küçültür'], 'Katalizör ileri ve geri aktifleşme enerjisini aynı miktarda düşürür; yalnız dengeye ulaşma süresi kısalır, denge sabiti ve bileşim aynı kalır.'),
  ('\'Sıcaklık artınca her tepkimenin denge sabiti büyür\' savına karşı en iyi karşı örnek hangisidir?', 'Ekzotermik bir tepkimede sıcaklık artınca K küçülür', ['Katalizörlü tepkimede K değişmez', 'Gaz mol sayısı değişen tepkimede K basınçla değişir', 'Sıcaklık artınca hız sabiti artar'], 'K\'nın sıcaklıkla değişimi ΔH işaretine bağlıdır. Ekzotermik tepkimelerde sıcaklık artışı K\'yı azaltır; yalnız endotermiklerde artırır.'),
  ('\'Yarı ömür bütün tepkimelerde sabittir\' denilebilir mi?', 'Hayır; yalnız birinci mertebede sabittir', ['Evet; yarı ömür her tepkimede sabittir', 'Evet; yarı ömür yalnızca katalizöre bağlıdır', 'Hayır; yarı ömür yalnız sıfır mertebede sabittir'], 'Birinci mertebede t½ = 0,693/k sabittir. İkinci mertebede t½ başlangıç derişimiyle ters, sıfırıncıda doğru orantılıdır.'),
  ('Bir öğrenci aktifleşme enerjisinin tepkime ısısına eşit olduğunu söylüyor. Aşağıdakilerden hangisi bu yanlışı doğru biçimde düzeltir?', 'Ea bariyerdir; ΔH ürün ile giren entalpi farkıdır', ['Ea, her zaman ve her tepkimede ΔH\'tan küçük kalır', 'Ea, ürünlerin toplam entalpisinin kendisidir', 'Ea, katalizörün bulunduğu ortamın entalpisidir'], 'Ea, girenlerden aktifleşmiş komplekse çıkmak için gereken enerjidir. ΔH ise ürün entalpisi eksi giren entalpisidir; ikisi farklı niceliklerdir.'),
  ('\'Endotermik tepkimeler hiçbir koşulda kendiliğinden gerçekleşemez\' savı hangi gerçekle çürütülür?', 'ΔS yeterince büyük pozitifse yüksek sıcaklıkta ΔG negatif olabilir', ['Endotermik tepkimelerde ΔG her zaman negatiftir', 'Endotermik tepkimeler ısı verir', 'Entropi hiçbir zaman değişmez'], 'İstemlilik ΔG = ΔH − TΔS ile belirlenir; ΔH > 0 olsa da ΔS > 0 ise yeterince yüksek T\'de ΔG < 0 olur (örneğin NH₄NO₃ çözünmesi).'),
  ('\'Sistemin entropisi hiçbir kendiliğinden süreçte azalamaz\' sözü hangi örnekle çürütülür?', 'Suyun 0 °C altında donması', ['Buzun erimesi', 'Gazın boşluğa yayılması', 'İki gazın karışması'], 'Donmada sistemin entropisi azalır; ancak çevreye verilen ısı çevrenin entropisini artırır ve evrenin toplam entropisi artmış olur.'),
  ('\'Katalizörsüz bir tepkime dengeye ulaşamaz\' ifadesi neden yanlıştır?', 'Katalizör hızı artırır; katalizörsüz de dengeye varılır', ['Katalizörsüz tepkimenin termodinamik denge sabiti tanımlanamaz', 'Katalizör olmadan hiçbir tepkime yürümez', 'Katalizör denge sabitini oluşturur'], 'Denge sabiti termodinamik bir niceliktir. Katalizör olmadan dengeye ulaşma yalnız çok daha uzun sürebilir.'),
  ('Bir öğrenci ekzotermik bir tepkimede sıcaklık arttığında hızın düştüğünü iddia ediyor. Aşağıdakilerden hangisi bu iddiayı doğru biçimde değerlendirir?', 'Hız (k) artar; düşen şey denge sabitidir', ['Hız gerçekten azalır, K artar', 'Hem hız hem K azalır', 'Hiçbir şey değişmez'], 'Sıcaklık artınca ileri ve geri hız sabitleri artar; ekzotermik dengede K azalır, yani denge girenlere kayar. Hızın düşmesi (kural olarak) söz konusu değildir.'),
  ('\'Bütün elementlerin standart oluşum entalpisi sıfırdır\' ifadesini hangisi düzeltir?', 'Yalnız standart hâldeki en kararlı biçimleri için sıfırdır', ['Hiçbir elementin oluşum entalpisi sıfır değildir', 'Yalnız gaz hâlindeki elementler için sıfırdır', 'Yalnız metal elementler için sıfırdır, ametallerde sıfır olmaz'], 'ΔH°f(element) = 0, elementin standart hâlindeki en kararlı biçimi için geçerlidir; örneğin C(grafit) için 0, C(elmas) için +1,9 kJ/mol\'dür.'),
  ('\'ΔS > 0 olan her tepkime kendiliğinden gerçekleşir\' savını hangisi çürütür?', 'ΔS > 0 olsa da ΔH çok pozitif, T düşükse ΔG > 0', ['ΔS > 0 olduğunda ΔG her koşulda ve her sıcaklıkta negatiftir', 'ΔS entalpiyi sıfırlar', 'ΔS yalnız katılarda önemlidir'], 'ΔG = ΔH − TΔS\'de büyük pozitif ΔH ve düşük T\'de −TΔS terimi yetersiz kalabilir; istemlilik yalnız ΔS\'ye bağlı değildir.'),
  ('Aynı derişimli HCl çözeltilerine eşit boyutlu Mg, Zn ve Cu parçaları atılıyor. Hidrojen gazı çıkış hızı büyükten küçüğe nasıl sıralanır?', 'Mg > Zn > Cu', ['Cu > Zn > Mg', 'Zn > Mg > Cu', 'Üçü de aynı hızda gaz çıkarır'], 'Metalin aktifliği arttıkça asitle tepkime hızı artar. Mg, Zn\'dan aktiftir; Cu hidrojenin altında olduğundan HCl\'den H₂ çıkarmaz.'),
  ('H₂(g) + ½O₂(g) → H₂O(s) için ΔH = −286 kJ ve ΔG = −237 kJ\'dir. Bir yakıt hücresinin teorik en yüksek verimi ΔG/ΔH oranıyla yaklaşık yüzde kaçtır?', '83', ['50', '100', '17'], 'Elektrik işi en fazla |ΔG| kadardır. Verim = 237/286 ≈ 0,83 yani %83\'tür. Isı motorlarının Carnot sınırından farklı olarak yakıt hücreleri bu verime yaklaşabilir.'),
  ('1 mol ideal gaz sabit basınçta 1 K ısıtılırken çevreye karşı yaptığı genleşme işinin büyüklüğü yaklaşık kaç J\'dir? (R = 8,314 J/(mol·K))', '8,3', ['83', '0,83', '101'], 'Sabit basınçta w = −PΔV = −nRΔT\'dir. n = 1 ve ΔT = 1 K için |w| = 8,314 J.'),
  ('Parafin mumu gibi faz değiştiren malzemeler güneş enerjili ısıtmada depo olarak kullanılır. Bu kullanım hangi özelliğe dayanır?', 'Erirken ısı depolayıp donarken geri vermeleri', ['Yanarak enerji vermeleri', 'Çok yüksek özgül ısıya sahip olmaları', 'Kimyasal bozunma ile ısı üretmeleri'], 'Erime sırasında büyük miktarda gizli ısı depolanır ve sıcaklık düşünce katılaşırken bu ısı geri verilir; sıcaklık bu sürede neredeyse sabit kalır.'),
  ('Gaz hâlindeki bir maddenin ısıtılması sabit basınçta sabit hacme göre daha fazla ısı gerektirir. Bunun nedeni nedir?', 'Sabit basınçta ısının bir kısmı genleşme işine harcanır', ['Sabit basınçta gaz ısıyı hiç tutmaz', 'Sabit hacimde iş sıfırdan büyüktür', 'Basınç ısıyı yok eder'], 'Sabit basınçta gaz genleşip çevreye iş yapar; sıcaklığı aynı miktar artırmak için ek enerji gerekir. Bu yüzden Cp > Cv\'dir.'),
  ('Ba(OH)₂·8H₂O ile NH₄SCN karışımı yürüdüğü hâlde soğuma yapıyor. Tepkimenin istemli olabilmesi için hangi büyüklük baskın olmalıdır?', 'Entropi artışı', ['Entalpi artışı', 'Aktifleşme enerjisi', 'Sıcaklık düşüşü'], 'Endotermik tepkimede ΔG negatif olabilmesi için sıvı ve gaz ürünlerden gelen büyük entropi artışı −TΔS terimini yeterince negatif yapmalıdır.'),
  ('Üre sentezinin ilk basamağı olan 2NH₃(g) + CO₂(g) ⇌ NH₂COONH₄ (karbamat) dengesinde yüksek basınç kullanılması neden uygundur?', 'Gaz mol sayısı 3\'ten 1\'e düştüğü için ürüne kayar', ['Basınç NH₃\'ü sıvılaştırıp CO₂\'yi tamamen çözer ve tüketir', 'Basınç aktifleşme enerjisini sıfırlar', 'Basınç artınca Kc değeri büyür ve ürün artar'], 'Girenlerde 3 mol gaz, ürün tarafında az gaz bulunduğundan basınç artışı Le Chatelier ilkesine göre dengeyi ürüne kaydırır.'),
  ('Metanol sentezinde CO + 2H₂ → CH₃OH tepkimesi yaklaşık 250 °C ve 50–100 atm\'de Cu/ZnO katalizörüyle yürütülür. Yüksek basıncın seçilme nedeni nedir?', 'Gaz mol sayısı 3\'ten 1\'e azaldığı için ürüne kayar', ['Katalizörü yüksek basınçta eritip yüzeyini yenilemek için', 'Tepkimeyi endotermik yapmak için', 'Hız sabitini sıfırlamak için'], 'Mol sayısı azalan gaz tepkimesinde basıncın artırılması metanol verimini artırır; katalizör ise düşük sıcaklıkta yeterli hız sağlar.'),
  ('Gaz hâlindeki bir maddenin birinci mertebeden bozunması sırasında kısmi basınç 40 dakikada dörtte bire iniyor (0,40 atm → 0,10 atm). Yarı ömür kaç dakikadır?', '20', ['10', '40,0', '80'], 'Basınç 4\'te 1\'ine inmiştir; bu iki yarı ömre eşittir. 40 dk = 2·t½ olduğundan t½ = 20 dk.'),
  ('Birinci mertebeden bir tepkimede [A] 0, 20 ve 40. dakikalarda sırasıyla 0,80; 0,40 ve 0,20 M ölçülüyor. [A] = 0,05 M\'ye düşmesi için başlangıçtan itibaren kaç dakika geçer?', '80', ['60', '100', '120'], 'Yarı ömür 20 dk\'dır. 0,80 → 0,05 M için 16 kat azalma, yani 4 yarı ömür gerekir: 4 × 20 = 80 dk.'),
  ('A(g) + B(g) ⇌ 2C(g) dengesinin Kc değeri 4\'tür. Aynı kapta 1 mol A ve 1 mol B ile başlanırsa dengede kaç mol C bulunur?', '1,0', ['0,5', '2,0', '0,67'], 'Δn = 0 olduğundan hacim sadeleşir. (2x)²/(1−x)² = 4 → 2x/(1−x) = 2 ve x = 0,5. C = 2x = 1,0 mol.'),
  ('Gücü 500 W olan bir su ısıtıcısı ısı kaybı olmadan 1,0 kg suyu 20 °C\'den 100 °C\'ye çıkarmak için yaklaşık kaç saniye çalışmalıdır? (c = 4,18 J/(g·°C))', '669', ['334', '1340', '80'], 'q = 1000 × 4,18 × 80 = 334 400 J. t = q/P = 334 400/500 ≈ 669 s (yaklaşık 11 dakika).'),
  ('Amonyak sentezi için kaynaklarda verilen mutlak entropiler N₂ 192, H₂ 131, NH₃ 193 J/(mol·K) alınırsa N₂ + 3H₂ → 2NH₃ denkleminin ΔS° değeri nedir?', '−199', ['+199', '−385', '+386'], 'ΔS° = 2(193) − [192 + 3(131)] = 386 − 585 = −199 J/K. Gaz mol sayısı 4\'ten 2\'ye düştüğünden negatiftir.'),
  ('Standart entropiler CaCO₃(k) 93, CaO(k) 40 ve CO₂(g) 214 J/(mol·K)\'dır. CaCO₃ → CaO + CO₂ için ΔS° kaç J/K\'dir?', '+161', ['−161', '+347', '+254'], 'ΔS° = (40 + 214) − 93 = +161 J/K. Gaz oluştuğu için entropi artar.'),
  ('Bir tepkime için ln k değerleri 1/T\'ye karşı çizildiğinde doğrunun y eksenini kestiği değer neyi verir?', 'ln A', ['Ea/R', '−Ea', 'ΔH'], 'ln k = ln A − (Ea/R)(1/T) bağıntısında 1/T = 0 için ln k = ln A olur; kesişim noktası ln A\'yı verir.'),
  ('Pembe renkli [Co(H₂O)₆]²⁺ + 4Cl⁻ ⇌ [CoCl₄]²⁻ (mavi) + 6H₂O dengesinde mavi çözeltiye su eklenince renk nasıl değişir?', 'Pembeye döner', ['Daha koyu maviye döner', 'Renksizleşir', 'Değişmez'], 'Su eklenince Cl⁻ derişimi düşer ve ürün tarafında su artar; denge girenler yönüne kayar, pembe kompleks oluşur.'),
  ('A(g) + B(g) ⇌ C(g) tepkimesi çözücü (inert gaz değil) eklenerek seyreltilirse ya da hacim artırılırsa dengeye etkisi nedir?', 'Gaz mol sayısı çok olan tarafa, girenlere', ['Gaz mol sayısı az olan ürüne doğru kayar', 'Denge hiçbir yöne kaymaz, sabit kalır', 'Önce ürüne kayar, sonra tamamen geri döner'], 'Hacim artınca basınç düşer; denge toplam gaz mol sayısı çok olan taraf olan A + B (2 mol) yönüne kayar.'),
  ('Su ve hidrojen sülfür (H₂S) benzer yapıdadır; buna rağmen suyun buharlaşma entalpisi (≈ 44 kJ/mol) H₂S\'inkinden (≈ 19 kJ/mol) çok yüksektir. Bunun nedeni nedir?', 'Suda moleküller arası hidrojen bağı bulunması', ['H₂S\'in daha ağır olması', 'Suyun kovalent bağlarının H₂S\'inkilerden çok zayıf olması', 'H₂S\'in iyonik bileşik olması'], 'Suda O–H···O hidrojen bağları vardır; buharlaştırmak için bu güçlü etkileşimlerin kırılması gerekir. H₂S\'te yalnız zayıf dipol–dipol ve London etkileşimleri vardır.'),
  ('Yakıtların \'üst ısıl değeri\' (brüt) ve \'alt ısıl değeri\' (net) arasındaki fark nedir?', 'Üst ısıl değerde yanma sonucu oluşan su sıvı olarak yoğuşur ve yoğuşma ısısı da hesaba katılır', ['Üst ısıl değer yakıtın kütlesi, alt ısıl değer hacmidir', 'Alt ısıl değerde oksijen kullanılmaz', 'İkisi tamamen aynıdır'], 'Üst ısıl değerde ürün H₂O sıvı hâlde kabul edilir; alt ısıl değerde ise buhar olarak çıktığı varsayılır. Aradaki fark suyun buharlaşma ısısıdır.'),
  ('Yoğuşmalı kombilerin geleneksel kombilere göre daha verimli olmasının termokimyasal nedeni nedir?', 'Baca gazındaki buharı yoğuşturup ısı kazanması', ['Yakıtı iki kat daha fazla yakarak sıcaklığı artırması', 'Suyu yanma odasında dondurarak ısı depolaması', 'Katalizör kullanması'], 'Doğal gazın yanmasında oluşan su buharı yoğuşurken yaklaşık 44 kJ/mol ısı verir; yoğuşmalı kombi bu ısıyı ısıtmada kullanarak üst ısıl değere yaklaşır.'),
  ('Aynı ısıtıcı ile ısıtılan eşit kütleli iki sıvıdan A\'nın sıcaklığı 10 dakikada 20 °C artarken B\'nin sıcaklığı 40 °C artıyor. Özgül ısılar için hangisi doğrudur?', 'c(A) = 2c(B)', ['c(B) = 2c(A)', 'c(A) = c(B)', 'c(A) = 4c(B)'], 'Aynı q ve m için ΔT özgül ısıyla ters orantılıdır. A\'nın ΔT\'si yarısı olduğundan özgül ısısı B\'nin iki katıdır.'),
  ('Hız yasası r = k[A]² olan bir tepkimede [A] = 0,20 M iken r = 8,0×10⁻³ M/s\'dir. [A] = 0,50 M iken hız kaç M/s olur?', '5,0×10⁻²', ['2,0×10⁻²', '8,0×10⁻²', '1,25×10⁻²'], 'k = 8,0×10⁻³/0,04 = 0,20 M⁻¹ s⁻¹. r = 0,20 × 0,25 = 5,0×10⁻² M/s.'),
  ('PCl₅(g) ⇌ PCl₃(g) + Cl₂(g) dengesinde 500 K\'de Kp = 1,0 atm\'dir. Kc = Kp/(RT)^Δn ilişkisiyle Kc yaklaşık kaç M\'dir? (R = 0,082 L·atm/(mol·K))', '0,024', ['1,00', '41,0', '0,82'], 'Δn = +1, RT = 0,082 × 500 = 41 L·atm/mol. Kc = Kp/RT = 1,0/41 ≈ 0,024 M.'),
  ('Katı bir katalizör kullanılan bir gaz tepkimesinde katalizör ince bir film hâlinde yüzeye sürülürse, aynı kütledeki iri parçaya göre hız nasıl değişir?', 'Artar; açığa çıkan yüzey alanı büyür', ['Azalır; kütle azalır', 'Değişmez; katalizör kütlesi aynıdır', 'Sıfırlanır'], 'Heterojen katalizde etkin yüzey alanı önemlidir. Aynı kütlenin ince film biçiminde yayılması aktif bölge sayısını artırır ve hızı yükseltir.'),
  ('İki basamaklı bir tepkimede birinci basamak ΔH = +30 kJ, Ea = 80 kJ; ikinci basamak ΔH = −70 kJ, Ea = 20 kJ\'dir. Toplam tepkimenin ΔH değeri ve hız belirleyen basamak hangisidir?', 'ΔH = −40 kJ; birinci basamak', ['ΔH = +100 kJ; ikinci basamak', 'ΔH = −40 kJ; ikinci basamak', 'ΔH = +40 kJ; birinci basamak'], 'ΔH\'lar toplanır: +30 − 70 = −40 kJ. Aktifleşme enerjisi büyük olan birinci basamak (80 kJ) en yavaş olduğundan hızı belirler.'),
  ('Aynı dengede iki farklı sıcaklıktaki K değerleri K(300 K) = 4,0 ve K(400 K) = 0,50\'dir. Bu veri ve Le Chatelier ilkesi birlikte yorumlanırsa hangisi doğrudur?', 'Tepkime ekzotermiktir; sıcaklık artınca girenler tercih edilir', ['Tepkime endotermiktir; sıcaklık artınca ürünler tercih edilir', 'Tepkime ΔH = 0\'dır', 'Gaz mol sayısı değişmemiştir'], 'Sıcaklık artınca K küçülüyorsa denge girenler yönüne kaymıştır; bu ekzotermik tepkimelerin özelliğidir.'),
  ('Yavaş basamağı değişmeyen iki basamaklı bir mekanizmada yalnız ikinci (hızlı) basamağı hızlandıran bir katalizör kullanılırsa toplam tepkime hızı nasıl etkilenir?', 'Hemen hemen değişmez; hızı yavaş basamak belirler', ['Çok büyük ölçüde artar', 'Yarıya düşer', 'Sıfırlanır'], 'Toplam hız en yavaş basamak tarafından sınırlanır. Hızlı basamağı daha da hızlandırmak yavaş basamağın hızını artırmayacağından toplam hız belirgin biçimde değişmez.'),
  ('Bir katalizör, katalizsiz yolun yanında yeni bir paralel tepkime yolu açıyorsa toplam tepkime hızı nasıl değişir?', 'İki yolun hızlarının toplamı olduğundan artar', ['Yalnız katalizsiz yolun hızına eşit kalır', 'Azalır', 'İki yolun hızlarının çarpımı olur'], 'Paralel yollarda toplam hız her yolun hızının toplamıdır. Katalizör ek ve düşük bariyerli bir yol sunduğu için toplam hız artar.'),
  ('1 mol CH₃COOH ile 1 mol C₂H₅OH karışımında esterleşme dengesinin Kc değeri 4\'tür. Dengede esterin mol sayısı kaçtır? (Hacim sabit, Δn = 0)', '0,67', ['0,50', '0,800', '1,00'], 'x mol ester oluşursa x²/(1−x)² = 4; x/(1−x) = 2 ve x = 2/3 ≈ 0,67 mol bulunur; ester verimi yaklaşık %67\'dir.'),
  ('İdeal bir gaz, yalıtılmış bir kapta vakuma serbestçe genleşiyor (Joule deneyi). Bu süreçte sistem için hangisi doğrudur?', 'q = 0, w = 0 ve ΔU = 0; sıcaklık değişmez', ['q > 0 ve sıcaklık artar', 'w < 0 ve sıcaklık düşer', 'ΔU < 0 olur'], 'Boşluğa genleşmede dış basınç sıfır olduğundan w = 0\'dır; yalıtılmış kapta q = 0\'dır. ΔU = 0 olduğundan ideal gazın sıcaklığı değişmez.'),
  ('Isı kapasitesi 10,0 kJ/°C olan bomba kalorimetresinde 0,0100 mol benzoik asit (ΔU_yanma ≈ −3227 kJ/mol) yakılıyor. Sıcaklık artışı yaklaşık kaç °C\'dir?', '3,23', ['32,3', '0,323', '1,0'], 'Açığa çıkan ısı 0,0100 × 3227 = 32,27 kJ\'dir. ΔT = q/C = 32,27/10,0 ≈ 3,23 °C.'),
  ('A + B → ürün tepkimesinin hız yasası r = k[A][B]\'dir. 100 mL 0,20 M A çözeltisi ile 100 mL 0,20 M B çözeltisi karıştırıldığında başlangıç hızı, derişimler karışımdan önceki değerlerle hesaplanan hızın kaçta kaçıdır?', '1/4', ['1,0/2', '1/8', '1,0'], 'Hacim iki katına çıkınca her iki derişim 0,10 M\'ye (yarıya) iner. r = k[A][B] olduğundan hız (1/2)(1/2) = 1/4\'üne düşer.'),
  ('Renkli bir girenin tükendiği bir tepkime spektrofotometre ile izleniyor. Soğurma (A) zamanla azalıyor ve ln A değerlerinin zamana karşı doğrusal olduğu görülüyor. Bu iki bilgi birlikte neyi gösterir?', 'A ∝ c olduğundan tepkime birinci mertebedir', ['Soğurma azaldığı için tepkime sıfırıncı mertebedir', 'Tepkime ikinci mertebedendir', 'Soğurma hız ile ilgisizdir'], 'Beer–Lambert yasasında A = εlc olduğundan soğurma derişimle orantılıdır. ln c\'nin zamanla doğrusal olması birinci mertebe kinetiğini gösterir.'),
  ('Kinetik deneyde belirli aralıklarla alınan örnekler analiz edilmeden önce buzlu suya batırılıp seyreltilir. Bunun amacı nedir?', 'Tepkimenin ilerlemesini durdurmak ya da yavaşlatmak', ['Tepkimeyi hızlandırarak analiz süresini mümkün olduğunca kısaltmak', 'Katalizör eklemek', 'Denge sabitini kalıcı olarak başka bir değere getirmek'], 'Soğutma ve seyreltme hız sabitini ve derişimleri düşürerek örneğin bileşimini analiz süresince sabit tutar; böylece ölçülen derişim, örnek alındığı andakini temsil eder.'),
  ('Alkanların yanma entalpileri metan −890, etan −1560, propan −2220 ve bütan −2877 kJ/mol\'dür. Her ek –CH₂– grubunun yaklaşık katkısı göz önüne alınarak pentanın yanma entalpisi yaklaşık kaç kJ/mol beklenir?', '−3540', ['−3200', '−4200', '−2900'], 'Ardışık farklar yaklaşık 660–670 kJ/mol\'dür. Bütana bir –CH₂– eklenince −2877 − 660 ≈ −3540 kJ/mol tahmin edilir.'),
  ('CaO(k) + CO₂(g) ⇌ CaCO₃(k) tepkimesi ekzotermiktir (ΔH ≈ −178 kJ). Kalsiyum döngüsü ile CO₂ yakalamada CO₂\'nin yaklaşık 650 °C\'de tutulup yaklaşık 900 °C\'de geri verilmesi nasıl açıklanır?', 'Düşük sıcaklık ürüne (CaCO₃), yüksek sıcaklık girenlere (CO₂) dengeyi kaydırır', ['Yüksek sıcaklık CaCO₃ oluşumunu artırır', 'Sıcaklık denge konumunu etkilemez', 'Yüksek sıcaklıkta katalizör çözülür'], 'Ekzotermik ileri yönde sıcaklık artınca K azalır; yüksek sıcaklıkta CaCO₃ ayrışarak CO₂ verir, daha düşük sıcaklıkta CaO CO₂\'yi bağlar.'),
  ('Karbonik anhidraz enzimi CO₂ + H₂O ⇌ H₂CO₃ dengesine ulaşılmasını milyonlarca kat hızlandırır. Bu enzimin denge üzerindeki etkisi için hangisi doğrudur?', 'Dengeye daha çabuk ulaşılır; K ve denge bileşimi değişmez', ['K milyonlarca kat artar', 'Denge ürünlere tamamen kayar', 'K sıfırlanır'], 'Enzim biyolojik bir katalizördür; ileri ve geri hızı aynı oranda artırır, dengeye varış süresini kısaltır ama denge sabitini değiştirmez.'),
  ('4,3 g sofra şekeri (sakkaroz, 342 g/mol) tamamen yandığında ΔH_yanma = −5640 kJ/mol\'e göre yaklaşık kaç kJ ısı açığa çıkar?', '71', ['5640', '18', '450'], '4,3 g sakkaroz 4,3/342 ≈ 0,0126 mol\'dür. Isı = 0,0126 × 5640 ≈ 71 kJ (yaklaşık 17 kcal).'),
  ('H• + H• → H₂ gibi radikal birleşmesi tepkimelerinin aktifleşme enerjisi sıfıra çok yakındır. Bunun sonucu nedir?', 'Hız, uygun çarpışma sıklığıyla sınırlı olacak kadar yüksektir', ['Tepkime çok yavaştır', 'Tepkime endotermiktir', 'Tepkime hiç gerçekleşmez'], 'Bağ oluşumu enerji açığa çıkarır ve geçiş için enerji bariyeri neredeyse yoktur; karşılaşan radikaller hemen birleşir.'),
  ('Sulu çözeltide H⁺ + OH⁻ → H₂O tepkimesi son derece hızlıdır ve hız çoğunlukla iyonların birbirine ulaşma (difüzyon) hızıyla sınırlanır. Bu durum neyi gösterir?', 'Aktifleşme enerjisi çok düşüktür, hız çarpışma sıklığına bağlıdır', ['Aktifleşme enerjisi çok büyüktür', 'Tepkime katalizörle yavaşlar', 'Tepkime endotermiktir'], 'İyon–iyon tepkimelerinde enerji bariyeri küçüktür; hız çözeltide taneciklerin karşılaşma sıklığıyla (difüzyon kontrollü) belirlenir.'),
  ('Bir ilacın bozunması birinci mertebedendir ve k = 0,0105 gün⁻¹\'dir. %10\'unun bozunması (kalan %90) için geçen süre, t₉₀ = 0,105/k bağıntısıyla yaklaşık kaç gündür?', '10', ['66', '0,0011', '100'], 't₉₀ = 0,105/0,0105 = 10 gün. İlaçların raf ömrü sıklıkla bu ölçütle belirlenir.'),
  ('Haber–Bosch sürecinde hammadde gazlar kükürt bileşiklerinden (örneğin H₂S) arındırılır. Bunun nedeni nedir?', 'Kükürt bileşikleri demir katalizörünü zehirler', ['Kükürt bileşikleri NH₃\'ü ayrıştırır', 'Kükürt bileşikleri basıncı düşürür', 'Kükürt ΔH değerini artırır'], 'Kükürt bileşikleri katalizör yüzeyine güçlü tutunarak aktif bölgeleri kapatır (katalizör zehirlenmesi). Bu yüzden besleme gazı önceden saflaştırılır.'),
  ('Temiz bir Mg şeridi HCl çözeltisine atıldığında bir süre gaz çıkışı gözlenmeyip sonra tepkime başlıyor. Bu gecikmenin başlıca nedeni nedir?', 'Mg yüzeyindeki MgO tabakasının önce asitte çözünmesi gerekmesi', ['Mg\'nin asitle hiç tepkimeye girmemesi', 'HCl\'nin önce ısınması', 'Katalizörün gecikmeyle oluşması'], 'Metal yüzeyi havayla oksitlenmiş durumdadır. Oksit tabakası çözünene kadar asit metalle temas edemez; ardından hızlı H₂ çıkışı başlar.'),
  ('Isıyla bozunan hassas bir vitamin içeren çözelti buzdolabında 4 °C\'de korunuyor. Bozunmanın aktifleşme enerjisi yüksek (≈ 100 kJ/mol) ise sıcaklık kontrolü neden özellikle önemlidir?', 'Yüksek Ea\'lı tepkimenin hızı sıcaklıkla çok daha duyarlı değişir', ['Yüksek Ea hızı sıcaklıktan bağımsız yapar', 'Düşük sıcaklıkta Ea artar', 'Sıcaklık yalnız ΔH\'ı etkiler'], 'Arrhenius bağıntısında Ea büyüdükçe ln k\'nın 1/T\'ye duyarlılığı artar; küçük sıcaklık artışı bozunma hızını belirgin yükseltir.'),
  ('Bir çözeltideki enzimli bir tepkimede sıcaklık 37 °C\'den 47 °C\'ye çıkarılınca hız önce artıyor sonra düşüyor. Aynı enzim için optimum sıcaklıktan sonra hız düşmesinin yorumu nedir?', 'Protein yapısının bozulması (denatürasyon) etkin enzim miktarını azaltır', ['Substrat tamamen biter', 'Aktifleşme enerjisi sonsuz olur', 'Enzim çoğalır'], 'Yüksek sıcaklıkta enzimin üç boyutlu yapısı bozulur ve aktif merkez işlevini kaybeder; hız sabiti artsa bile etkin enzim miktarı azaldığından hız düşer.'),
  ('Yüksek fırında C(k) + CO₂(g) ⇌ 2CO(g) tepkimesi endotermiktir. Fırının sıcak bölgesinde CO\'nun baskın olması nasıl açıklanır?', 'Yüksek sıcaklık endotermik ileri yönü (CO oluşumunu) destekler', ['Yüksek sıcaklık CO oluşumunu engeller', 'Basınç hiçbir etki yapmaz', 'Katı karbon denge ifadesine girer'], 'Endotermik tepkimede sıcaklık yükselince K büyür ve denge CO tarafına kayar. Aynı zamanda gaz mol sayısı artmaktadır (1 → 2).'),
  ('Yüksek fırında Fe₂O₃ + 3CO ⇌ 2Fe + 3CO₂ dengesinde ortamda CO fazlası bulundurulur ve oluşan CO₂ sürekli uzaklaşır. Bunun amacı nedir?', 'Dengeyi demir oluşumu yönüne kaydırmak', ['Dengeyi Fe₂O₃ oluşumu yönüne kaydırmak', 'Katalizör oluşturmak', 'Basıncı sıfırlamak'], 'Giren (CO) derişimini yüksek, ürün (CO₂) derişimini düşük tutmak Q\'yu K\'nın altında tutar; böylece cevherin demire indirgenmesi tamamlanır.'),
  ('Bir kokteyl bardağındaki 250 g su 25 °C\'den 0 °C\'ye soğutuluyor. Isı kaybı olmadan bunu yalnız 0 °C\'deki buz eriterek yapmak için yaklaşık kaç gram buz gerekir? (c = 4,18 J/(g·°C), erime ısısı 334 J/g)', '78', ['25', '250', '8'], 'Suyun vereceği ısı 250 × 4,18 × 25 = 26 125 J\'dür. Buz erirken 334 J/g alır: m = 26 125/334 ≈ 78 g.'),
  ('Büyük ve karmaşık moleküller arasındaki tepkimelerde, çarpışma sıklığı yüksek olsa bile hız sabiti küçük kalabilir. Bu durumun çarpışma teorisindeki açıklaması nedir?', 'Yalnız uygun yönelimle çarpışmalar etkindir; yönelim (sterik) çarpanı küçüktür', ['Çarpışma hiç olmaz', 'Moleküllerin enerjisi sıfırdır', 'Etkin çarpışmalar tüm çarpışmalardır'], 'Büyük moleküllerde tepkime merkezine uygun yönelimde ulaşma olasılığı düşüktür; sterik çarpan küçük olduğundan A değeri düşer ve hız yavaşlar.'),
  ('Aynı enzimin iki farklı substrat için Michaelis sabitleri 0,10 mM ve 5,0 mM\'dir. Enzimin substrata ilgisi hakkında hangisi söylenebilir?', 'Km = 0,10 mM olan substrata ilgisi daha yüksektir', ['Km = 5,0 mM olan substrata ilgisi daha yüksektir', 'İlgi iki substratta eşittir', 'Km ilgiyle ilgili değildir'], 'Küçük Km, yarı-maksimum hıza düşük substrat derişiminde ulaşıldığını gösterir; yani enzim o substrata daha güçlü ilgi gösterir.'),
  ('Substrat doygunluğundaki (yüksek substrat derişimli) bir enzimli tepkimede enzim miktarı iki katına çıkarılırsa maksimum hız (Vmax) nasıl değişir?', 'İki katına çıkar', ['Değişmez', 'Yarıya düşer', 'Dört katına çıkar'], 'Vmax = k_cat[E]toplam olduğundan enzim derişimiyle doğru orantılıdır; doygunlukta aktif merkez sayısı iki katına çıkınca hız iki katına çıkar.'),
  ('A ⇌ B tepkimesinin ileri hız sabiti 3,0×10⁻³ s⁻¹, geri hız sabiti 1,0×10⁻³ s⁻¹\'dir. Yalnız 1,0 M A ile başlanırsa dengede [B] kaç M olur?', '0,75', ['0,25', '0,50', '0,330'], 'Kc = k₁/k₋₁ = 3\'tür. [B]/[A] = 3 ve [A] + [B] = 1,0 olduğundan [B] = 0,75 M bulunur.'),
  ('HI(g) için ΔH°f = +26 kJ/mol\'dür. Bu değer HI\'nın ısıtıldığında hangi davranışı göstermesiyle uyumludur?', 'Elementlerinden yüksek enerjili olduğundan ayrışmaya yatkındır', ['Elementlerinden daha kararlıdır ve hiç ayrışmaz', 'Isıtılınca entalpisi sıfır olur', 'Ayrışması endotermiktir'], 'ΔH°f > 0 ise bileşik elementlerinden entalpice yüksektir; HI\'nın ayrışması ekzotermiktir (ΔH ≈ −26 kJ/mol) ve yüksek sıcaklıkta ayrışma desteklenir.'),
  ('Aktifleşmiş kompleks ile ara ürün arasındaki ayrımda \'izole edilebilirlik\' açısından hangisi doğrudur?', 'Ara ürün bazen ayrıştırılabilir, aktifleşmiş kompleks ise izole edilemez', ['Aktifleşmiş kompleks şişede saklanabilir', 'İkisi de kararlı maddelerdir', 'İkisi de izole edilemez ve enerji profilinde çukurdadır'], 'Ara ürün enerji profilinde bir çukurdur ve kimi zaman yakalanabilir. Aktifleşmiş kompleks ise enerji tepesindeki geçici yapıdır (ömrü yaklaşık 10⁻¹³ s) ve ayrılamaz.'),
  ('Sabit sıcaklıkta kapalı bir kapta 2NO(g) + O₂(g) ⇌ 2NO₂(g) dengesi kuruldu. Kabın hacmi iki katına çıkarılırsa dengedeki NO₂ miktarı (mol) nasıl değişir?', 'Azalır; denge gaz mol sayısı çok olan girenler yönüne kayar', ['Artar', 'Değişmez', 'Önce artar sonra sıfır olur'], 'Hacim artınca basınç düşer. Girenlerde 3 mol, üründe 2 mol gaz bulunduğundan denge girenlere kayar ve NO₂ mol sayısı azalır.'),
  ('Sert suyun ısıtılmasıyla kap yüzeyinde kazan taşı (CaCO₃) birikir: Ca²⁺ + 2HCO₃⁻ ⇌ CaCO₃ + CO₂ + H₂O. Isıtma sırasında kazan taşının oluşumunu hızlandıran etken nedir?', 'CO₂\'nin sıcak sudan uçup gitmesiyle dengenin ürünlere kayması', ['Ca²⁺ iyonlarının buharlaşması', 'Suyun donması', 'HCO₃⁻ iyonlarının katalizör olması'], 'CO₂ sıcak suda az çözündüğünden ortamdan uzaklaşır; Le Chatelier ilkesine göre denge CaCO₃ oluşumu yönüne kayar ve kazan taşı çöker.'),
  ('Metanın yanma entalpisi −890 kJ/mol\'dür (CH₄ = 16 g/mol). 1 kWh (3600 kJ) ısı elde etmek için yaklaşık kaç gram metan yakılmalıdır?', '65', ['16', '890', '4,0'], '3600/890 ≈ 4,04 mol CH₄ gerekir. Kütle = 4,04 × 16 ≈ 65 g.'),
  ('Bir gazın suda çözünmesi (örneğin CO₂(g) → CO₂(suda)) sırasında sistemin entropisi nasıl değişir?', 'Azalır; gaz molekülleri çözeltide sınırlı hareket eder', ['Artar', 'Değişmez', 'Her zaman sıfırdır'], 'Gaz fazındaki molekül büyük bir hacimde serbestçe hareket ederken çözeltide hareket serbestliği azalır; ΔS < 0\'dır. Bu yüzden gaz çözünürlüğü sıcaklıkla azalır.'),
  ('ΔG = ΔH − TΔS bağıntısına göre sıcaklık sıfıra çok yaklaştığında istemlilik hangi büyüklükle belirlenir?', 'Entalpi değişimiyle (ΔH)', ['Entropi değişimiyle (ΔS)', 'Serbest enerjiyle değil, hızla', 'Hiçbir büyüklükle'], 'T → 0 iken TΔS terimi ihmal edilir ve ΔG ≈ ΔH olur; düşük sıcaklıklarda genellikle ekzotermik süreçler istemlidir.'),
  ('N₂(g) + 3H₂(g) → 2NH₃(g) tepkimesinin ΔH değeri −92 kJ olarak yazılmıştır. Bu değerdeki \'kJ\' birimi neyi ifade eder?', 'Denklemdeki katsayılara göre gerçekleşen tepkime başına entalpi değişimini', ['1 mol N₂ başına değişimi', '1 gram NH₃ başına değişimi', 'Her zaman 1 mol ürün başına değişimi'], 'Termokimyasal denklemde ΔH, denklem yazıldığı biçimde (1 mol N₂ ile 3 mol H₂\'nin 2 mol NH₃ vermesi) tepkime başına verilir; NH₃ başına −46 kJ/mol\'dür.'),
  ('Kabartma tozundaki NaHCO₃\'ın oda sıcaklığında kararlı olup fırında bozunması (2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O) Gibbs enerjisi açısından nasıl açıklanır?', 'ΔH > 0 ve ΔS > 0 olduğundan yalnız yüksek sıcaklıkta ΔG < 0 olur', ['ΔH < 0 olduğundan her sıcaklıkta kendiliğinden olur', 'ΔS < 0 olduğundan fırında olur', 'ΔG sıcaklıktan bağımsızdır'], 'Bozunma gaz çıkışıyla entropiyi artırır fakat endotermiktir. −TΔS terimi ancak yeterince yüksek sıcaklıkta ΔH\'ı yenerek ΔG\'yi negatif yapar.'),
  ('Bir kalorimetre deneyinde aynı miktar reaktant kuvvetli asit–kuvvetli baz yerine zayıf asit–kuvvetli baz ile karıştırıldığında ölçülen sıcaklık artışı nasıl olur?', 'Daha küçük olur; zayıf asidin iyonlaşması enerji gerektirir', ['Daha büyük olur', 'Aynı olur', 'Negatif olur'], 'Zayıf asidin iyonlaşması endotermik olduğundan açığa çıkan net ısı azalır ve ΔT daha küçük ölçülür.'),
];
